window.ENGLISHBOOK_DATA = {"siteTitle":"EnglishBook","tagline":"Read stories. Learn English. Speak naturally.","featuredSeries":"anne","books":[{"id":"anne-of-green-gables","series":"anne","title":"Anne of Green Gables","author":"L. M. Montgomery","status":"published","totalChapters":38,"hero":"images/anne-of-green-gables/hero.webp","cover":"images/books/anne-of-green-gables.webp","description":"Follow Anne Shirley as she comes to live at Green Gables and fills a quiet world with imagination, friendship, mistakes, and joy."},{"id":"anne-of-avonlea","series":"anne","title":"Anne of Avonlea","author":"L. M. Montgomery","status":"coming-soon","cover":"images/books/anne-of-avonlea.webp","description":"Anne grows into a young teacher while Avonlea brings new responsibilities, friendships, and surprises."},{"id":"anne-of-the-island","series":"anne","title":"Anne of the Island","author":"L. M. Montgomery","status":"coming-soon","cover":"images/books/anne-of-the-island.webp","description":"Anne leaves Avonlea for college and begins a new stage of friendship, independence, and love."}],"chapters":{"anne-of-green-gables":[{"number":1,"title":"Mrs. Rachel Lynde Is Surprised","file":"content/anne-of-green-gables/chapter-01.md","image":"images/anne-of-green-gables/chapter-01.webp"},{"number":2,"title":"Matthew Cuthbert Is Surprised","file":"content/anne-of-green-gables/chapter-02.md","image":"images/anne-of-green-gables/chapter-02.webp"},{"number":3,"title":"Marilla Cuthbert Is Surprised","file":"content/anne-of-green-gables/chapter-03.md","image":"images/anne-of-green-gables/chapter-03.webp"},{"number":4,"title":"Morning at Green Gables","file":"content/anne-of-green-gables/chapter-04.md","image":"images/anne-of-green-gables/chapter-04.webp"},{"number":5,"title":"Anne's History","file":"content/anne-of-green-gables/chapter-05.md","image":"images/anne-of-green-gables/chapter-05.webp"},{"number":6,"title":"Marilla Makes Up Her Mind","file":"content/anne-of-green-gables/chapter-06.md","image":"images/anne-of-green-gables/chapter-06.webp"},{"number":7,"title":"Anne Says Her Prayers","file":"content/anne-of-green-gables/chapter-07.md","image":"images/anne-of-green-gables/chapter-07.webp"},{"number":8,"title":"Anne's Bringing-Up Is Begun","file":"content/anne-of-green-gables/chapter-08.md","image":"images/anne-of-green-gables/chapter-08.webp"},{"number":9,"title":"Mrs. Rachel Lynde Is Properly Horrified","file":"content/anne-of-green-gables/chapter-09.md","image":"images/anne-of-green-gables/chapter-09.webp"},{"number":10,"title":"Anne's Apology","file":"content/anne-of-green-gables/chapter-10.md","image":"images/anne-of-green-gables/chapter-10.webp"},{"number":11,"title":"Anne's Impressions of Sunday School","file":"content/anne-of-green-gables/chapter-11.md","image":"images/anne-of-green-gables/chapter-11.webp"},{"number":12,"title":"A Solemn Vow and Promise","file":"content/anne-of-green-gables/chapter-12.md","image":"images/anne-of-green-gables/chapter-12.webp"},{"number":13,"title":"The Delights of Anticipation","file":"content/anne-of-green-gables/chapter-13.md","image":"images/anne-of-green-gables/chapter-13.webp"},{"number":14,"title":"Anne's Confession","file":"content/anne-of-green-gables/chapter-14.md","image":"images/anne-of-green-gables/chapter-14.webp"},{"number":15,"title":"A Tempest in the School Teapot","file":"content/anne-of-green-gables/chapter-15.md","image":"images/anne-of-green-gables/chapter-15.webp"},{"number":16,"title":"Diana Is Invited to Tea with Tragic Results","file":"content/anne-of-green-gables/chapter-16.md","image":"images/anne-of-green-gables/chapter-16.webp"},{"number":17,"title":"A New Interest in Life","file":"content/anne-of-green-gables/chapter-17.md","image":"images/anne-of-green-gables/chapter-17.webp"},{"number":18,"title":"Anne to the Rescue","file":"content/anne-of-green-gables/chapter-18.md","image":"images/anne-of-green-gables/chapter-18.webp"},{"number":19,"title":"A Concert, a Catastrophe, and a Confession","file":"content/anne-of-green-gables/chapter-19.md","image":"images/anne-of-green-gables/chapter-19.webp"},{"number":20,"title":"A Good Imagination Gone Wrong","file":"content/anne-of-green-gables/chapter-20.md","image":"images/anne-of-green-gables/chapter-20.webp"},{"number":21,"title":"A New Departure in Flavorings","file":"content/anne-of-green-gables/chapter-21.md","image":"images/anne-of-green-gables/chapter-21.webp"},{"number":22,"title":"Anne Is Invited Out to Tea","file":"content/anne-of-green-gables/chapter-22.md","image":"images/anne-of-green-gables/chapter-22.webp"},{"number":23,"title":"Anne Comes to Grief in an Affair of Honor","file":"content/anne-of-green-gables/chapter-23.md","image":"images/anne-of-green-gables/chapter-23.webp"},{"number":24,"title":"Miss Stacy and Her Pupils Get Up a Concert","file":"content/anne-of-green-gables/chapter-24.md","image":"images/anne-of-green-gables/chapter-24.webp"},{"number":25,"title":"Matthew Insists on Puffed Sleeves","file":"content/anne-of-green-gables/chapter-25.md","image":"images/anne-of-green-gables/chapter-25.webp"},{"number":26,"title":"The Story Club Is Formed","file":"content/anne-of-green-gables/chapter-26.md","image":"images/anne-of-green-gables/chapter-26.webp"},{"number":27,"title":"Vanity and Vexation of Spirit","file":"content/anne-of-green-gables/chapter-27.md","image":"images/anne-of-green-gables/chapter-27.webp"},{"number":28,"title":"An Unfortunate Lily Maid","file":"content/anne-of-green-gables/chapter-28.md","image":"images/anne-of-green-gables/chapter-28.webp"},{"number":29,"title":"An Epoch in Anne's Life","file":"content/anne-of-green-gables/chapter-29.md","image":"images/anne-of-green-gables/chapter-29.webp"},{"number":30,"title":"The Queen's Class Is Organized","file":"content/anne-of-green-gables/chapter-30.md","image":"images/anne-of-green-gables/chapter-30.webp"},{"number":31,"title":"Where the Brook and River Meet","file":"content/anne-of-green-gables/chapter-31.md","image":"images/anne-of-green-gables/chapter-31.webp"},{"number":32,"title":"The Pass List Is Out","file":"content/anne-of-green-gables/chapter-32.md","image":"images/anne-of-green-gables/chapter-32.webp"},{"number":33,"title":"The Hotel Concert","file":"content/anne-of-green-gables/chapter-33.md","image":"images/anne-of-green-gables/chapter-33.webp"},{"number":34,"title":"A Queen's Girl","file":"content/anne-of-green-gables/chapter-34.md","image":"images/anne-of-green-gables/chapter-34.webp"},{"number":35,"title":"The Winter at Queen's","file":"content/anne-of-green-gables/chapter-35.md","image":"images/anne-of-green-gables/chapter-35.webp"},{"number":36,"title":"The Glory and the Dream","file":"content/anne-of-green-gables/chapter-36.md","image":"images/anne-of-green-gables/chapter-36.webp"},{"number":37,"title":"The Reaper Whose Name Is Death","file":"content/anne-of-green-gables/chapter-37.md","image":"images/anne-of-green-gables/chapter-37.webp"},{"number":38,"title":"The Bend in the Road","file":"content/anne-of-green-gables/chapter-38.md","image":"images/anne-of-green-gables/chapter-38.webp"}]},"chapterContent":{"content/anne-of-green-gables/chapter-01.md":"# Chapter 1 — Mrs. Rachel Lynde Is Surprised\n\n## Story Summary — A2–B1 Level\n\nIt is a quiet afternoon in the small village of Avonlea on Prince Edward Island. Mrs. Rachel Lynde is sitting by her window. She likes to know what is happening in the neighborhood and usually notices anything unusual.\n\nThen she sees Matthew Cuthbert driving past her house. This surprises her. Matthew is a very quiet and shy man. He does not often go out, and today he is wearing his best clothes.\n\nMrs. Rachel immediately begins to wonder where he is going. She decides to visit Green Gables, where Matthew lives with his sister, Marilla. When Mrs. Rachel arrives, Marilla gives her some surprising news: she and Matthew have decided to adopt an orphan boy.\n\nMatthew is getting older, and the farm is becoming difficult for him to manage alone. They hope that a boy of about ten or eleven can live with them, go to school, and also help Matthew with the farm work. Mrs. Rachel is shocked. She worries that bringing a child they know nothing about into their home could cause trouble.\n\nShe tells Marilla several frightening stories she has heard about adopted children. Marilla understands her concerns, but she and Matthew have already made the decision. Matthew is now on his way to the train station to pick up the boy.\n\nMrs. Rachel leaves Green Gables still thinking about the surprising news. But neither woman knows that Matthew is not going to find the boy they are expecting.\n\n## Conversation 1 — What’s Going On?\n\n*A modern conversation inspired by this chapter.*\nNeighbor: Rachel, you look surprised. What’s going on?\nRachel: You won’t believe it. Matthew and Marilla have decided to take in an orphan.\nNeighbor: Really? How did that come about?\nRachel: They need someone to help Matthew out around the farm.\nNeighbor: That’s a big decision.\nRachel: Exactly. I don’t know how it’s going to work out.\n\n### Phrasal Verbs\n\n- take in — allow someone to live in your home and care for them. They decided to take in an orphan.\n- come about — happen or develop. How did this situation come about?\n- help someone out — help someone with a problem or task. Can you help me out this weekend?\n- work out — develop successfully. I hope everything works out.\n\n## Conversation 2 — Matthew’s Trip\n\n*A modern conversation inspired by this chapter.*\nRachel: Where has Matthew gone?\nMarilla: He’s gone to the station to pick up the boy.\nRachel: You really went through with it?\nMarilla: Yes. We’ve been thinking about it for months.\nRachel: You’re certainly taking on a lot of responsibility.\nMarilla: Matthew can’t keep up with all the farm work by himself anymore.\n\n### Useful Expressions\n\n- pick someone up — go somewhere and bring someone back. I’ll pick you up at the airport.\n- go through with — do something you had planned, especially something difficult.\n- take on — accept responsibility or work.\n- keep up with — continue at the necessary speed or level.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"take in\", \"prompt\": \"Which expression best means “allow someone to live in your home and care for them”?\", \"options\": [\"take over\", \"take in\", \"turn down\"], \"answer\": \"take in\", \"explanation\": \"“take in” means allow someone to live in your home and care for them.\"}, {\"type\": \"fill\", \"target\": \"come about\", \"prompt\": \"Complete the expression: “come ___”\", \"answer\": \"about\", \"accepted\": [\"about\"], \"explanation\": \"The complete expression is “come about,” meaning happen or develop.\"}, {\"type\": \"dialogue\", \"target\": \"help someone out\", \"prompt\": \"Moving day\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"I’m moving apartments on Saturday.\"}, {\"speaker\": \"Leo\", \"text\": \"That sounds like a lot of work.\"}, {\"speaker\": \"Mia\", \"text\": \"I still have six boxes to carry downstairs.\"}, {\"speaker\": \"Leo\", \"text\": \"Don’t worry. I can ___ for an hour before lunch.\"}], \"options\": [\"turn down\", \"help you out\", \"take over\"], \"answer\": \"help you out\", \"explanation\": \"“help someone out” means help someone with a problem or task.\"}, {\"type\": \"order\", \"target\": \"pick someone up\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"you\", \"up\", \"pick\"], \"answer\": \"pick you up\", \"explanation\": \"The natural phrase is “pick you up.” “pick someone up” means go somewhere and bring someone back.\"}, {\"type\": \"dialogue\", \"target\": \"keep up with\", \"prompt\": \"A busy week at work\", \"dialogue\": [{\"speaker\": \"Nina\", \"text\": \"You look exhausted. Is everything okay?\"}, {\"speaker\": \"Sam\", \"text\": \"We have three deadlines this week.\"}, {\"speaker\": \"Nina\", \"text\": \"Are you managing all the new tasks?\"}, {\"speaker\": \"Sam\", \"text\": \"Barely. I’m having trouble ___ all the emails and meetings.\"}], \"options\": [\"take over\", \"keeping up with\", \"turn down\"], \"answer\": \"keeping up with\", \"explanation\": \"“keep up with” means continue at the necessary speed or level.\"}]\n```\n","content/anne-of-green-gables/chapter-02.md":"# Chapter 2 — Matthew Cuthbert Is Surprised\n\n## Story Summary — A2–B1 Level\n\nMatthew Cuthbert drives to the train station to pick up the orphan boy he and Marilla are expecting. When he arrives, however, there is no boy waiting for him. Instead, Matthew sees a thin, red-haired girl sitting at the station with a small bag beside her.\n\nHer name is Anne Shirley. The stationmaster explains that Anne is the child who was sent from the orphanage. Matthew realizes that there has been a mistake. Matthew is extremely shy, especially around women and girls.\n\nHe does not know how to explain the problem to Anne, so he decides to take her home and let Marilla deal with the situation. Anne is delighted to see him. As soon as they leave the station, she begins talking, and she hardly stops. Anne tells Matthew about herself, her imagination, and the things she loves.\n\nShe is especially excited by the beautiful countryside around them. As they travel toward Green Gables, Anne gives imaginative names to the places they pass, including the “White Way of Delight” and the “Lake of Shining Waters.” Matthew is not used to talking very much, but he enjoys listening to Anne. Her excitement and imagination make the quiet journey much more interesting.\n\nAnne tells him that she has always dreamed of having a real home. Matthew begins to feel uncomfortable because he knows Marilla wanted a boy, not a girl. Anne is so happy that he cannot bring himself to tell her the truth.\n\nFinally, they arrive at Green Gables. Matthew knows that Marilla is about to discover that something has gone very wrong.\n\n## Conversation 1 — At the Station\n\n*A modern conversation inspired by this chapter.*\nStationmaster: Are you here to pick up the child from the orphanage?\nMatthew: Yes, but I was expecting a boy.\nStationmaster: This girl is the only child who showed up.\nMatthew: There must have been a mistake.\nStationmaster: You’ll have to sort it out with the orphanage.\n\n### Phrasal Verbs\n\n- pick someone up — go somewhere to collect someone.\n- show up — arrive or appear somewhere.\n- sort something out — solve a problem or confusing situation.\n\n## Conversation 2 — On the Way Home\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I can’t believe I’m finally going to have a home.\nMatthew: We’ll have to see how things go.\nAnne: I’ve been looking forward to this for so long.\nAnne: I hope Marilla and I get along.\n\n### Useful Expressions\n\n- see how things go — wait and see what happens before deciding.\n- look forward to — feel happy and excited about something in the future.\n- get along with — have a friendly relationship with someone.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"pick someone up\", \"prompt\": \"Which expression best means “go somewhere to collect someone”?\", \"options\": [\"take over\", \"pick someone up\", \"turn down\"], \"answer\": \"pick someone up\", \"explanation\": \"“pick someone up” means go somewhere to collect someone.\"}, {\"type\": \"fill\", \"target\": \"show up\", \"prompt\": \"Complete the expression: “show ___”\", \"answer\": \"up\", \"accepted\": [\"up\"], \"explanation\": \"The complete expression is “show up,” meaning arrive or appear somewhere.\"}, {\"type\": \"dialogue\", \"target\": \"sort something out\", \"prompt\": \"A billing problem\", \"dialogue\": [{\"speaker\": \"Ava\", \"text\": \"My phone bill is much higher than usual.\"}, {\"speaker\": \"Ben\", \"text\": \"Did you call the company?\"}, {\"speaker\": \"Ava\", \"text\": \"Not yet. I’m not sure what happened.\"}, {\"speaker\": \"Ben\", \"text\": \"Call customer service. They should be able to ___ for you.\"}], \"options\": [\"sort it out\", \"take over\", \"turn down\"], \"answer\": \"sort it out\", \"explanation\": \"“sort something out” means solve a problem or confusing situation.\"}, {\"type\": \"order\", \"target\": \"look forward to\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"forward\", \"to\", \"Friday\", \"look\"], \"answer\": \"look forward to Friday\", \"explanation\": \"The natural phrase is “look forward to Friday.” “look forward to” means feel happy and excited about something in the future.\"}, {\"type\": \"dialogue\", \"target\": \"get along with\", \"prompt\": \"A new roommate\", \"dialogue\": [{\"speaker\": \"Kai\", \"text\": \"How is your new roommate?\"}, {\"speaker\": \"Lena\", \"text\": \"She’s friendly and very considerate.\"}, {\"speaker\": \"Kai\", \"text\": \"So living together is going well?\"}, {\"speaker\": \"Lena\", \"text\": \"Yes, I really ___ her.\"}], \"options\": [\"take over\", \"get along with\", \"turn down\"], \"answer\": \"get along with\", \"explanation\": \"“get along with” means have a friendly relationship with someone.\"}]\n```\n","content/anne-of-green-gables/chapter-03.md":"# Chapter 3 — Marilla Cuthbert Is Surprised\n\n## Story Summary — A2–B1 Level\n\nWhen Matthew and Anne arrive at Green Gables, Marilla comes to meet them and is shocked. She was expecting a boy, but Matthew has brought home a red-haired girl. Matthew explains that Anne was waiting at the station and that there had clearly been a mistake.\n\nAnne quickly understands the situation. She realizes that Matthew and Marilla did not want her at all. They wanted a boy who could help with the farm. Anne is heartbroken. She begins to cry and says that this is the worst thing that has ever happened to her.\n\nShe had been so excited about finally having a home, and now she believes she will have to return to the orphanage. Marilla thinks Anne is dramatic, but she also begins to feel sorry for her. Anne says she wishes her name were something beautiful such as Cordelia.\n\nIf Marilla must call her Anne, she asks her to spell it with an “e.” Marilla tells Anne that she can stay at Green Gables for the night. They will decide what to do the next day. Meanwhile, Matthew quietly tells Marilla that perhaps they could keep Anne.\n\nMarilla is surprised again. They had planned to adopt a boy for a practical reason, but Matthew has already become fond of Anne.\n\n## Conversation 1 — There’s Been a Mistake\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: Matthew, what’s going on? Where’s the boy?\nMatthew: He never showed up. Anne was waiting instead.\nMarilla: Someone must have mixed things up.\nMatthew: That’s what I thought.\nMarilla: We’ll have to find out what happened.\n\n### Phrasal Verbs\n\n- show up — arrive.\n- mix something up — confuse one thing with another.\n- find out — discover information.\n\n## Conversation 2 — What Should We Do?\n\n*A modern conversation inspired by this chapter.*\n\nMatthew: Maybe we could keep her around.\nMarilla: We agreed to get a boy.\nMatthew: Why don’t we think it over?\nMarilla: We can’t simply change our minds tonight.\n\n### Useful Expressions\n\n- keep someone around — allow someone to remain with you.\n- think something over — consider something carefully.\n- change your mind — decide something different.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"show up\", \"prompt\": \"Which expression best means “arrive”?\", \"options\": [\"take over\", \"show up\", \"turn down\"], \"answer\": \"show up\", \"explanation\": \"“show up” means arrive.\"}, {\"type\": \"fill\", \"target\": \"mix something up\", \"prompt\": \"Complete the expression: “mix something ___”\", \"answer\": \"up\", \"accepted\": [\"up\"], \"explanation\": \"The complete expression is “mix something up,” meaning confuse one thing with another.\"}, {\"type\": \"dialogue\", \"target\": \"find out\", \"prompt\": \"A restaurant plan\", \"dialogue\": [{\"speaker\": \"Ella\", \"text\": \"Do you know what time the restaurant closes?\"}, {\"speaker\": \"Noah\", \"text\": \"I’m not sure.\"}, {\"speaker\": \"Ella\", \"text\": \"We don’t want to arrive too late.\"}, {\"speaker\": \"Noah\", \"text\": \"I’ll check their website and ___ for us.\"}], \"options\": [\"take over\", \"turn down\", \"find out\"], \"answer\": \"find out\", \"explanation\": \"“find out” means discover information.\"}, {\"type\": \"order\", \"target\": \"think something over\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"over\", \"think\"], \"answer\": \"think it over\", \"explanation\": \"The natural phrase is “think it over.” “think something over” means consider something carefully.\"}, {\"type\": \"dialogue\", \"target\": \"change your mind\", \"prompt\": \"Dinner plans\", \"dialogue\": [{\"speaker\": \"Maya\", \"text\": \"I thought you wanted Thai food tonight.\"}, {\"speaker\": \"Ethan\", \"text\": \"I did, but I had Thai for lunch.\"}, {\"speaker\": \"Maya\", \"text\": \"So you want something different now?\"}, {\"speaker\": \"Ethan\", \"text\": \"Yes, I ___ after lunch.\"}], \"options\": [\"take over\", \"changed my mind\", \"turn down\"], \"answer\": \"changed my mind\", \"explanation\": \"“change your mind” means decide something different.\"}]\n```\n","content/anne-of-green-gables/chapter-04.md":"# Chapter 4 — Morning at Green Gables\n\n## Story Summary — A2–B1 Level\n\nThe next morning, Anne wakes up in the small bedroom at Green Gables. For a moment, she does not remember where she is. Then she looks outside. The morning is beautiful.\n\nAnne sees trees, flowers, fields, and the countryside around Green Gables. She becomes so excited by the beauty outside that she almost forgets how unhappy she was the night before. At breakfast, Marilla notices that Anne is hardly eating.\n\nAnne explains that she is too upset to have much of an appetite because she still believes she will be sent away. Marilla tells her that they have not made a final decision yet. Later, Marilla prepares to take Anne to Mrs. Spencer, the woman who arranged the adoption.\n\nShe wants to find out exactly how the mistake happened. Anne understands what the trip probably means. She expects that she will eventually be sent back to the orphanage.\n\nEven so, Anne continues to notice the beauty around Green Gables. Marilla finds Anne’s constant talking unusual and sometimes tiring, but she is beginning to see that Anne is intelligent, sensitive, and full of life.\n\n## Conversation 1 — The Morning After\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: You hardly ate anything.\nAnne: I’m worried you’ll send me back.\nMarilla: We haven’t decided anything yet.\nAnne: I tried to cheer myself up by looking outside.\n\n### Phrasal Verbs\n\n- send someone back — make someone return to where they came from.\n- cheer up — become happier or make someone happier.\n\n## Conversation 2 — Finding Out What Happened\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: We’re going to Mrs. Spencer’s today.\nAnne: Are you going to take me back?\nMarilla: First, I want to find out how this happened.\nAnne: Maybe everything will turn out all right.\n\n### Useful Expressions\n\n- take someone back — return someone to a previous place.\n- find out — discover information.\n- turn out — develop or end in a particular way.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"send someone back\", \"prompt\": \"Which expression best means “make someone return to where they came from”?\", \"options\": [\"take over\", \"send someone back\", \"turn down\"], \"answer\": \"send someone back\", \"explanation\": \"“send someone back” means make someone return to where they came from.\"}, {\"type\": \"fill\", \"target\": \"cheer up\", \"prompt\": \"Complete the expression: “cheer ___”\", \"answer\": \"up\", \"accepted\": [\"up\"], \"explanation\": \"The complete expression is “cheer up,” meaning become happier or make someone happier.\"}, {\"type\": \"dialogue\", \"target\": \"take someone back\", \"prompt\": \"Returning a child home\", \"dialogue\": [{\"speaker\": \"Sofia\", \"text\": \"Is Emma staying for dinner?\"}, {\"speaker\": \"Luis\", \"text\": \"No, her parents are expecting her by six.\"}, {\"speaker\": \"Sofia\", \"text\": \"How is she getting home?\"}, {\"speaker\": \"Luis\", \"text\": \"I’ll ___ after we finish the game.\"}], \"options\": [\"turn down\", \"take her back\", \"take over\"], \"answer\": \"take her back\", \"explanation\": \"“take someone back” means return someone to a previous place.\"}, {\"type\": \"order\", \"target\": \"find out\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"out\", \"the\", \"answer\", \"find\"], \"answer\": \"find out the answer\", \"explanation\": \"The natural phrase is “find out the answer.” “find out” means discover information.\"}, {\"type\": \"dialogue\", \"target\": \"turn out\", \"prompt\": \"A new restaurant\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"Was the new restaurant good?\"}, {\"speaker\": \"Sam\", \"text\": \"I was unsure because the reviews were mixed.\"}, {\"speaker\": \"Mia\", \"text\": \"So how was it?\"}, {\"speaker\": \"Sam\", \"text\": \"It ___ to be excellent.\"}], \"options\": [\"take over\", \"turned out\", \"turn down\"], \"answer\": \"turned out\", \"explanation\": \"“turn out” means develop or end in a particular way.\"}]\n```\n","content/anne-of-green-gables/chapter-05.md":"# Chapter 5 — Anne's History\n\n## Story Summary — A2–B1 Level\n\nOn the way to Mrs. Spencer’s house, Marilla asks Anne about her past. Anne explains that her parents, Walter and Bertha Shirley, were teachers. They died when Anne was still a baby. A woman named Mrs. Thomas took Anne in.\n\nAnne lived with the Thomas family and helped care for their children. Although she was very young, she had many responsibilities. After Mr. Thomas died, Mrs. Thomas could no longer keep Anne.\n\nAnne then went to live with Mrs. Hammond, who had many children. Anne again spent much of her time caring for younger children. When Mr. Hammond died, Anne could no longer stay there either.\n\nEventually, she was sent to an orphanage, where she lived for several months before Mrs. Spencer arranged for her to come to Prince Edward Island. As Marilla listens, she begins to understand Anne better. Anne has never had a stable, loving home of her own.\n\nShe often helped adults and cared for children, but rarely had someone who truly cared for her. Anne uses imagination to make difficult experiences easier to bear. Her story affects Marilla, who begins to question whether sending Anne away is really the right thing to do.\n\n## Conversation 1 — Anne’s Childhood\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: Who looked after you after your parents died?\nAnne: Mrs. Thomas took me in at first.\nMarilla: And after that?\nAnne: I eventually ended up with another family.\n\n### Phrasal Verbs\n\n- look after — take care of someone.\n- take someone in — allow someone to live in your home.\n- end up — finally arrive at a situation or place, often unexpectedly.\n\n## Conversation 2 — A Difficult Past\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: You’ve had to put up with a lot.\nAnne: I suppose so.\nMarilla: How did you get through it?\nAnne: My imagination helped me get away from unhappy thoughts.\n\n### Useful Expressions\n\n- put up with — accept an unpleasant situation.\n- get through — survive or deal with a difficult experience.\n- get away from — escape or take a break from something unpleasant.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"look after\", \"prompt\": \"Which expression best means “take care of someone”?\", \"options\": [\"take over\", \"look after\", \"turn down\"], \"answer\": \"look after\", \"explanation\": \"“look after” means take care of someone.\"}, {\"type\": \"fill\", \"target\": \"take someone in\", \"prompt\": \"Complete the expression: “take someone ___”\", \"answer\": \"in\", \"accepted\": [\"in\"], \"explanation\": \"The complete expression is “take someone in,” meaning allow someone to live in your home.\"}, {\"type\": \"dialogue\", \"target\": \"end up\", \"prompt\": \"A changed evening plan\", \"dialogue\": [{\"speaker\": \"Owen\", \"text\": \"Did you go to the outdoor concert?\"}, {\"speaker\": \"Lily\", \"text\": \"No, it started raining.\"}, {\"speaker\": \"Owen\", \"text\": \"So what did you do instead?\"}, {\"speaker\": \"Lily\", \"text\": \"We ___ watching a movie at home.\"}], \"options\": [\"ended up\", \"take over\", \"turn down\"], \"answer\": \"ended up\", \"explanation\": \"“end up” means finally arrive at a situation or place, often unexpectedly.\"}, {\"type\": \"order\", \"target\": \"put up with\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"up\", \"with\", \"the\", \"noise\", \"put\"], \"answer\": \"put up with the noise\", \"explanation\": \"The natural phrase is “put up with the noise.” “put up with” means accept an unpleasant situation.\"}, {\"type\": \"dialogue\", \"target\": \"get through\", \"prompt\": \"A long phone queue\", \"dialogue\": [{\"speaker\": \"Jin\", \"text\": \"Were you able to reach the airline?\"}, {\"speaker\": \"Nora\", \"text\": \"Eventually.\"}, {\"speaker\": \"Jin\", \"text\": \"You were on hold forever.\"}, {\"speaker\": \"Nora\", \"text\": \"Yes, but I finally ___ to an agent.\"}], \"options\": [\"take over\", \"got through\", \"turn down\"], \"answer\": \"got through\", \"explanation\": \"“get through” means survive or deal with a difficult experience.\"}]\n```\n","content/anne-of-green-gables/chapter-06.md":"# Chapter 6 — Marilla Makes Up Her Mind\n\n## Story Summary — A2–B1 Level\n\nMarilla and Anne arrive at Mrs. Spencer’s house. Marilla explains that there has been a mistake: she and Matthew asked for a boy, but Anne was sent instead. Mrs. Spencer is surprised and embarrassed, but she quickly suggests a solution.\n\nMrs. Blewett is looking for a girl to help with her children and household work, so Anne could live with her. Then Mrs. Blewett arrives. Marilla knows she has a reputation for being strict and difficult. Mrs. Blewett looks at Anne mainly as someone who can work for her.\n\nAnne immediately becomes frightened. Marilla realizes that she cannot simply hand the girl over to someone she does not trust. Marilla tells Mrs. Spencer that she will take Anne back to Green Gables while she and Matthew think about the situation. When they return home, Matthew makes it clear that he wants Anne to stay.\n\nMarilla finally agrees. Anne can remain at Green Gables. Marilla also makes one thing clear: if Anne is going to stay, she must be properly raised, educated, and taught how to behave. Anne is finally going to have a home.\n\n## Conversation 1 — Another Possibility\n\n*A modern conversation inspired by this chapter.*\n\nMrs. Spencer: Mrs. Blewett could take Anne in.\nMarilla: I’m not sure about that.\nMrs. Spencer: She needs someone to help out.\nMarilla: I need time to think it over.\n\n### Phrasal Verbs\n\n- take someone in — provide someone with a place to live.\n- help out — give practical help.\n- think something over — consider something carefully.\n\n## Conversation 2 — The Decision\n\n*A modern conversation inspired by this chapter.*\n\nMatthew: What are we going to do?\nMarilla: I’ve made up my mind. She can stay.\nMatthew: I’m glad you’ve come around.\nMarilla: Don’t look so pleased.\nMatthew: I knew you’d warm up to her.\n\n### Useful Expressions\n\n- make up your mind — make a decision.\n- come around — change your opinion and begin to agree.\n- warm up to someone — gradually begin to like someone.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"take someone in\", \"prompt\": \"Which expression best means “provide someone with a place to live”?\", \"options\": [\"take over\", \"take someone in\", \"turn down\"], \"answer\": \"take someone in\", \"explanation\": \"“take someone in” means provide someone with a place to live.\"}, {\"type\": \"fill\", \"target\": \"help out\", \"prompt\": \"Complete the expression: “help ___”\", \"answer\": \"out\", \"accepted\": [\"out\"], \"explanation\": \"The complete expression is “help out,” meaning give practical help.\"}, {\"type\": \"dialogue\", \"target\": \"think something over\", \"prompt\": \"A job offer\", \"dialogue\": [{\"speaker\": \"Iris\", \"text\": \"Did you accept the new job?\"}, {\"speaker\": \"Mark\", \"text\": \"Not yet. The offer is good, but the commute is long.\"}, {\"speaker\": \"Iris\", \"text\": \"You don’t have to decide today.\"}, {\"speaker\": \"Mark\", \"text\": \"Right. I’m going to ___ tonight.\"}], \"options\": [\"take over\", \"turn down\", \"think it over\"], \"answer\": \"think it over\", \"explanation\": \"“think something over” means consider something carefully.\"}, {\"type\": \"order\", \"target\": \"make up your mind\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"up\", \"your\", \"mind\", \"make\"], \"answer\": \"make up your mind\", \"explanation\": \"The natural phrase is “make up your mind.” “make up your mind” means make a decision.\"}, {\"type\": \"dialogue\", \"target\": \"warm up to someone\", \"prompt\": \"A new coworker\", \"dialogue\": [{\"speaker\": \"Ben\", \"text\": \"How do you like the new manager?\"}, {\"speaker\": \"Sara\", \"text\": \"At first I thought she was too serious.\"}, {\"speaker\": \"Ben\", \"text\": \"And now?\"}, {\"speaker\": \"Sara\", \"text\": \"I’m starting to ___. She’s actually very helpful.\"}], \"options\": [\"take over\", \"warm up to her\", \"turn down\"], \"answer\": \"warm up to her\", \"explanation\": \"“warm up to someone” means gradually begin to like someone.\"}]\n```\n","content/anne-of-green-gables/chapter-07.md":"# Chapter 7 — Anne Says Her Prayers\n\n## Story Summary — A2–B1 Level\n\nThat evening, Marilla begins teaching Anne the habits she expects at Green Gables. She tells Anne to keep her room tidy and to say her prayers before bed. Anne surprises Marilla by admitting that she has never really learned how to pray.\n\nAnne knows a formal description of God from the orphanage, but she does not feel close to Him. She even says that she once blamed God for giving her red hair. Marilla is shocked and decides that Anne needs religious instruction.\n\nMarilla first tries to teach Anne a traditional children's prayer. Then she lets Anne pray in her own words. Anne thanks God for the beautiful things she has seen at Green Gables and asks to be allowed to stay there.\n\nShe also hopes she might become pretty when she grows up. Her prayer is unusual but sincere. Marilla is both worried and touched. She decides that Anne should attend Sunday school and learn more about religion and proper behavior.\n\nFor Marilla, raising Anne is clearly going to require patience.\n\n## Conversation 1 — Bedtime\n\n*A modern conversation inspired by this chapter.*\nMarilla: Before you turn in, you need to say your prayers.\nAnne: I don't really know how.\nMarilla: Then we'll go over it together.\nAnne: Could I say what I'm really thinking?\nMarilla: Yes, but try not to get carried away.\n\n### Phrasal Verbs\n\n- turn in — go to bed. I'm tired. I think I'll turn in early.\n- go over — review or explain carefully. Can we go over the instructions again?\n- get carried away — become too excited. I got carried away and talked for an hour.\n\n## Conversation 2 — Learning Something New\n\n*A modern conversation inspired by this chapter.*\n\nAnne: What if I mess up?\nMarilla: Then you learn from it and try again.\nAnne: I think I can keep at it.\nMarilla: Good. You'll pick things up little by little.\n\n### Useful Expressions\n\n- mess up — make a mistake. I messed up the recipe.\n- keep at it — continue trying. It's difficult, but keep at it.\n- pick up — learn gradually. She picked up English quickly.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"turn in\", \"prompt\": \"Which expression best means “go to bed”?\", \"options\": [\"take over\", \"turn in\", \"turn down\"], \"answer\": \"turn in\", \"explanation\": \"“turn in” means go to bed.\"}, {\"type\": \"fill\", \"target\": \"go over\", \"prompt\": \"Complete the expression: “go ___”\", \"answer\": \"over\", \"accepted\": [\"over\"], \"explanation\": \"The complete expression is “go over,” meaning review or explain carefully.\"}, {\"type\": \"dialogue\", \"target\": \"get carried away\", \"prompt\": \"Online shopping\", \"dialogue\": [{\"speaker\": \"Amy\", \"text\": \"I only meant to buy one shirt.\"}, {\"speaker\": \"Jo\", \"text\": \"But you have four packages.\"}, {\"speaker\": \"Amy\", \"text\": \"I know. The sale was too tempting.\"}, {\"speaker\": \"Jo\", \"text\": \"Looks like you ___ a little.\"}], \"options\": [\"turn down\", \"got carried away\", \"take over\"], \"answer\": \"got carried away\", \"explanation\": \"“get carried away” means become too excited.\"}, {\"type\": \"order\", \"target\": \"mess up\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"up\", \"mess\"], \"answer\": \"mess it up\", \"explanation\": \"The natural phrase is “mess it up.” “mess up” means make a mistake.\"}, {\"type\": \"dialogue\", \"target\": \"keep at it\", \"prompt\": \"Learning guitar\", \"dialogue\": [{\"speaker\": \"Nora\", \"text\": \"I still can’t play this song smoothly.\"}, {\"speaker\": \"Dan\", \"text\": \"You’ve only practiced it for three days.\"}, {\"speaker\": \"Nora\", \"text\": \"It’s frustrating.\"}, {\"speaker\": \"Dan\", \"text\": \"Just ___. It’ll get easier.\"}], \"options\": [\"take over\", \"keep at it\", \"turn down\"], \"answer\": \"keep at it\", \"explanation\": \"“keep at it” means continue trying.\"}]\n```\n","content/anne-of-green-gables/chapter-08.md":"# Chapter 8 — Anne's Bringing-Up Is Begun\n\n## Story Summary — A2–B1 Level\n\nThe next morning, Marilla tells Anne that she and Matthew have decided to keep her at Green Gables. Anne is so happy that she can hardly believe it. She wants to hug Marilla, but Marilla is not comfortable showing affection so openly.\n\nMarilla explains that Anne can stay if she tries to behave properly and obey the rules. Anne promises to do her best. She is eager to belong somewhere and to become the kind of girl Marilla wants her to be. Anne soon asks about other children nearby.\n\nMarilla tells her about Diana Barry, a girl who lives close by. Anne immediately hopes Diana will become the close friend she has always dreamed of having. Matthew is delighted that Anne is staying.\n\nUnlike Marilla, he does not worry much about correcting her. He simply enjoys having her around. Green Gables is already changing. The quiet house now has Anne's questions, stories, excitement, and mistakes in it.\n\nMarilla realizes that bringing Anne up will not be simple, but she has accepted the responsibility.\n\n## Conversation 1 — You Can Stay\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: We've decided you can stay.\nAnne: Really? You're not going to send me away?\nMarilla: No, but you'll have to follow through on your\npromises.\nAnne: I will. I'll do my best.\n\n### Phrasal Verbs\n\n- send someone away — make someone leave. They decided not to send him away.\n- follow through on — do what you promised. You need to follow through on your commitment.\n\n## Conversation 2 — A Possible Friend\n\n*A modern conversation inspired by this chapter.*\n\nAnne: Do you think Diana and I will get along?\nMarilla: You'll have to meet her and find out.\nAnne: I hope we hit it off right away.\nMarilla: Try to calm down until you actually meet her.\n\n### Useful Expressions\n\n- get along — have a friendly relationship. I get along with my neighbors.\n- find out — discover information. I'll call and find out.\n- hit it off — quickly become friendly. We hit it off immediately.\n- calm down — become less excited or upset. Take a minute to calm down.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"send someone away\", \"prompt\": \"Which expression best means “make someone leave”?\", \"options\": [\"take over\", \"send someone away\", \"turn down\"], \"answer\": \"send someone away\", \"explanation\": \"“send someone away” means make someone leave.\"}, {\"type\": \"fill\", \"target\": \"follow through on\", \"prompt\": \"Complete the expression: “follow through ___”\", \"answer\": \"on\", \"accepted\": [\"on\"], \"explanation\": \"The complete expression is “follow through on,” meaning do what you promised.\"}, {\"type\": \"dialogue\", \"target\": \"get along\", \"prompt\": \"A family trip\", \"dialogue\": [{\"speaker\": \"June\", \"text\": \"How did the kids do on the long drive?\"}, {\"speaker\": \"Paul\", \"text\": \"Much better than I expected.\"}, {\"speaker\": \"June\", \"text\": \"No fighting?\"}, {\"speaker\": \"Paul\", \"text\": \"Hardly any. They really ___ yesterday.\"}], \"options\": [\"got along\", \"take over\", \"turn down\"], \"answer\": \"got along\", \"explanation\": \"“get along” means have a friendly relationship.\"}, {\"type\": \"order\", \"target\": \"find out\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"out\", \"the\", \"answer\", \"find\"], \"answer\": \"find out the answer\", \"explanation\": \"The natural phrase is “find out the answer.” “find out” means discover information.\"}, {\"type\": \"dialogue\", \"target\": \"hit it off\", \"prompt\": \"Meeting someone new\", \"dialogue\": [{\"speaker\": \"Lia\", \"text\": \"How was dinner with your cousin and her friend?\"}, {\"speaker\": \"Max\", \"text\": \"Great. Her friend and I talked for two hours.\"}, {\"speaker\": \"Lia\", \"text\": \"Sounds like you liked each other right away.\"}, {\"speaker\": \"Max\", \"text\": \"Yeah, we really ___.\"}], \"options\": [\"take over\", \"hit it off\", \"turn down\"], \"answer\": \"hit it off\", \"explanation\": \"“hit it off” means quickly become friendly.\"}]\n```\n","content/anne-of-green-gables/chapter-09.md":"# Chapter 9 — Mrs. Rachel Lynde Is Properly Horrified\n\n## Story Summary — A2–B1 Level\n\nTwo weeks after Anne's arrival, Mrs. Rachel Lynde visits Green Gables to see her. Marilla admits that she has already grown fond of Anne and that the house feels different with her there. When Anne comes inside, Mrs. Rachel looks at her closely and comments that she is thin and not pretty.\n\nWorst of all, she makes fun of Anne's red hair. Anne's red hair is one of her greatest insecurities. She becomes furious and shouts at Mrs. Rachel.\n\nMarilla is horrified. After Mrs. Rachel leaves, Marilla tells Anne that insulting a visitor is unacceptable even if the visitor was rude first. Anne refuses to apologize because she believes she was defending herself. Marilla sends her to her room until she is willing to say sorry.\n\nMatthew quietly sympathizes with Anne, but Marilla insists that Anne must learn self-control.\n\n## Conversation 1 — Losing Your Temper\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: You can't blow up at people like that.\nAnne: But she picked on my hair!\nMarilla: You still went too far.\nAnne: I couldn't hold back.\n\n### Phrasal Verbs\n\n- blow up at — suddenly become angry with someone.\n- pick on — criticize or treat someone unfairly.\n- hold back — control an emotion or action.\n\n## Conversation 2 — The Apology\n\n*A modern conversation inspired by this chapter.*\n\nMatthew: Maybe you should get it over with and apologize.\nAnne: Marilla won't give in, will she?\nMatthew: Probably not. Then you can make up with Mrs. Lynde.\n\n### Useful Expressions\n\n- get it over with — finish something unpleasant.\n- give in — stop resisting.\n- make up with — become friendly again after an argument.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"blow up at\", \"prompt\": \"Which expression best means “suddenly become angry with someone”?\", \"options\": [\"take over\", \"blow up at\", \"turn down\"], \"answer\": \"blow up at\", \"explanation\": \"“blow up at” means suddenly become angry with someone.\"}, {\"type\": \"fill\", \"target\": \"pick on\", \"prompt\": \"Complete the expression: “pick ___”\", \"answer\": \"on\", \"accepted\": [\"on\"], \"explanation\": \"The complete expression is “pick on,” meaning criticize or treat someone unfairly.\"}, {\"type\": \"dialogue\", \"target\": \"hold back\", \"prompt\": \"Giving feedback\", \"dialogue\": [{\"speaker\": \"Zoe\", \"text\": \"Did you tell the team what you thought?\"}, {\"speaker\": \"Ian\", \"text\": \"Not all of it.\"}, {\"speaker\": \"Zoe\", \"text\": \"Why not?\"}, {\"speaker\": \"Ian\", \"text\": \"I ___ because I didn’t want to embarrass anyone.\"}], \"options\": [\"take over\", \"turn down\", \"held back\"], \"answer\": \"held back\", \"explanation\": \"“hold back” means control an emotion or action.\"}, {\"type\": \"order\", \"target\": \"get it over with\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"over\", \"with\", \"get\"], \"answer\": \"get it over with\", \"explanation\": \"The natural phrase is “get it over with.” “get it over with” means finish something unpleasant.\"}, {\"type\": \"dialogue\", \"target\": \"give in\", \"prompt\": \"Bedtime negotiation\", \"dialogue\": [{\"speaker\": \"Mom\", \"text\": \"Did Leo finally go to bed?\"}, {\"speaker\": \"Dad\", \"text\": \"Yes, but he asked for one more story three times.\"}, {\"speaker\": \"Mom\", \"text\": \"Did you read another one?\"}, {\"speaker\": \"Dad\", \"text\": \"I ___ in the end.\"}], \"options\": [\"take over\", \"gave in\", \"turn down\"], \"answer\": \"gave in\", \"explanation\": \"“give in” means stop resisting.\"}]\n```\n","content/anne-of-green-gables/chapter-10.md":"# Chapter 10 — Anne's Apology\n\n## Story Summary — A2–B1 Level\n\nAnne remains in her room because she does not want to apologize. Matthew secretly asks her to do it so the punishment can end. Anne finally agrees. At Mrs. Rachel's house, her apology becomes far more dramatic than Marilla expected.\n\nAnne kneels down, admits that she behaved badly, and passionately asks for forgiveness. Mrs. Rachel is surprised but pleased. She accepts the apology and even tells Anne that her red hair may become a nicer color as she grows older. On the way home, Anne admits that apologizing was almost enjoyable because she could make it dramatic.\n\nMarilla tries not to laugh. The conflict is repaired. Anne has learned that relationships sometimes require humility, while Marilla learns that Anne experiences even apologies with unusual intensity.\n\n## Conversation 1 — Owning Up\n\n*A modern conversation inspired by this chapter.*\n\nMatthew: Just own up to what you did.\nAnne: I suppose I should get it over with.\nMatthew: Then you two can start over.\n\n### Phrasal Verbs\n\n- own up to — admit that you did something wrong.\n- get it over with — finish an unpleasant task.\n- start over — begin again.\n\n## Conversation 2 — Afterward\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: Mrs. Lynde seems to have come around.\nAnne: I'm glad. Next time I'll try not to lash out.\nMarilla: Good. Learn from what happened.\n\n### Useful Expressions\n\n- come around — change your opinion positively.\n- lash out — suddenly speak or act angrily.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"own up to\", \"prompt\": \"Which expression best means “admit that you did something wrong”?\", \"options\": [\"take over\", \"own up to\", \"turn down\"], \"answer\": \"own up to\", \"explanation\": \"“own up to” means admit that you did something wrong.\"}, {\"type\": \"fill\", \"target\": \"get it over with\", \"prompt\": \"Complete the expression: “get it over ___”\", \"answer\": \"with\", \"accepted\": [\"with\"], \"explanation\": \"The complete expression is “get it over with,” meaning finish an unpleasant task.\"}, {\"type\": \"dialogue\", \"target\": \"start over\", \"prompt\": \"A document mistake\", \"dialogue\": [{\"speaker\": \"Rina\", \"text\": \"Why are you rewriting the form?\"}, {\"speaker\": \"Tom\", \"text\": \"I entered the wrong information in several places.\"}, {\"speaker\": \"Rina\", \"text\": \"Can you edit it?\"}, {\"speaker\": \"Tom\", \"text\": \"It’s faster to delete this copy and ___.\"}], \"options\": [\"turn down\", \"start over\", \"take over\"], \"answer\": \"start over\", \"explanation\": \"“start over” means begin again.\"}, {\"type\": \"order\", \"target\": \"come around\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"around\", \"come\"], \"answer\": \"come around\", \"explanation\": \"The natural phrase is “come around.” “come around” means change your opinion positively.\"}, {\"type\": \"dialogue\", \"target\": \"lash out\", \"prompt\": \"Stress after work\", \"dialogue\": [{\"speaker\": \"Eva\", \"text\": \"You sounded angry with me earlier.\"}, {\"speaker\": \"Luke\", \"text\": \"I know. I had a terrible day at work.\"}, {\"speaker\": \"Eva\", \"text\": \"I was only asking a question.\"}, {\"speaker\": \"Luke\", \"text\": \"I’m sorry. I shouldn’t have ___ at you.\"}], \"options\": [\"take over\", \"lashed out\", \"turn down\"], \"answer\": \"lashed out\", \"explanation\": \"“lash out” means suddenly speak or act angrily.\"}]\n```\n","content/anne-of-green-gables/chapter-11.md":"# Chapter 11 — Anne's Impressions of Sunday School\n\n## Story Summary — A2–B1 Level\n\nMarilla makes Anne plain new dresses and sends her to church and Sunday school. Anne is grateful to have proper clothes, but she secretly wishes for fashionable puffed sleeves. On the way, Anne enjoys the countryside and decorates her hat with wildflowers.\n\nShe thinks it looks beautiful. At church, however, Anne is disappointed. She had imagined something inspiring, but she finds the sermon long and difficult. She also feels that Sunday school involves too much memorizing and not enough real thinking.\n\nAnne later tells Marilla exactly what she thought. Her honesty worries Marilla, but it also shows that Anne wants things to have real meaning. Anne is learning the customs of Avonlea, but she is not giving up the imagination and curiosity that make her different.\n\n## Conversation 1 — Getting Ready\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: Are you ready to head off to church?\nAnne: Yes, although my dress doesn't exactly stand out.\nMarilla: You're not going there to show off.\n\n### Phrasal Verbs\n\n- head off — leave for a place.\n- stand out — be noticeably different.\n- show off — try to attract attention.\n\n## Conversation 2 — After Church\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: How did Sunday school go?\nAnne: I tried to pay attention, but my mind wandered.\nMarilla: You'll get used to it.\n\n### Useful Expressions\n\n- go — happen or progress. How did the interview go?\n- pay attention — listen carefully.\n- get used to — become comfortable with something.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"head off\", \"prompt\": \"Which expression best means “leave for a place”?\", \"options\": [\"take over\", \"head off\", \"turn down\"], \"answer\": \"head off\", \"explanation\": \"“head off” means leave for a place.\"}, {\"type\": \"fill\", \"target\": \"stand out\", \"prompt\": \"Complete the expression: “stand ___”\", \"answer\": \"out\", \"accepted\": [\"out\"], \"explanation\": \"The complete expression is “stand out,” meaning be noticeably different.\"}, {\"type\": \"dialogue\", \"target\": \"show off\", \"prompt\": \"At the gym\", \"dialogue\": [{\"speaker\": \"Mina\", \"text\": \"Why is Alex lifting such a heavy weight?\"}, {\"speaker\": \"Rob\", \"text\": \"His friends are watching.\"}, {\"speaker\": \"Mina\", \"text\": \"He usually doesn’t lift that much.\"}, {\"speaker\": \"Rob\", \"text\": \"I think he’s trying to ___.\"}], \"options\": [\"show off\", \"take over\", \"turn down\"], \"answer\": \"show off\", \"explanation\": \"“show off” means try to attract attention.\"}, {\"type\": \"order\", \"target\": \"pay attention\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"attention\", \"pay\"], \"answer\": \"pay attention\", \"explanation\": \"The natural phrase is “pay attention.” “pay attention” means listen carefully.\"}, {\"type\": \"dialogue\", \"target\": \"get used to\", \"prompt\": \"A new commute\", \"dialogue\": [{\"speaker\": \"Nate\", \"text\": \"How’s the train commute?\"}, {\"speaker\": \"Priya\", \"text\": \"The first week was tiring.\"}, {\"speaker\": \"Nate\", \"text\": \"Is it getting easier?\"}, {\"speaker\": \"Priya\", \"text\": \"Yes, I’m starting to ___ the early mornings.\"}], \"options\": [\"take over\", \"get used to\", \"turn down\"], \"answer\": \"get used to\", \"explanation\": \"“get used to” means become comfortable with something.\"}]\n```\n","content/anne-of-green-gables/chapter-12.md":"# Chapter 12 — A Solemn Vow and Promise\n\n## Story Summary — A2–B1 Level\n\nMarilla arranges for Anne to meet Diana Barry. Anne is extremely excited because she has always dreamed of having a true best friend. Anne and Diana are left alone to get acquainted.\n\nAnne quickly asks Diana whether she will become her \"bosom friend.\" Diana agrees, though she is less dramatic about it. Outside, the girls make a serious promise to remain friends forever. Anne treats the moment like an important ceremony.\n\nDiana happily joins her. Their friendship develops immediately. Diana is kind and practical, and she enjoys Anne's imaginative personality. Anne finally has someone her own age with whom she can share thoughts and adventures.\n\nWhen Matthew later gives Anne chocolates, she wants to share half with Diana. Marilla is pleased by Anne's generous spirit.\n\n## Conversation 1 — Meeting Diana\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I hope we can get to know each other.\nDiana: I'd like that.\nAnne: Maybe we'll hit it off.\nDiana: I think we already have.\n\n### Phrasal Verbs\n\n- get to know — gradually learn more about someone.\n- hit it off — quickly become friendly.\n\n## Conversation 2 — A Promise\n\n*A modern conversation inspired by this chapter.*\n\nAnne: We must never fall out.\nDiana: And if we do, we'll talk it out.\nAnne: Then we can always count on each other.\n\n### Useful Expressions\n\n- fall out — have an argument and stop being friendly.\n- talk it out — discuss a problem until it is resolved.\n- count on — depend on someone.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"get to know\", \"prompt\": \"Which expression best means “gradually learn more about someone”?\", \"options\": [\"take over\", \"get to know\", \"turn down\"], \"answer\": \"get to know\", \"explanation\": \"“get to know” means gradually learn more about someone.\"}, {\"type\": \"fill\", \"target\": \"hit it off\", \"prompt\": \"Complete the expression: “hit it ___”\", \"answer\": \"off\", \"accepted\": [\"off\"], \"explanation\": \"The complete expression is “hit it off,” meaning quickly become friendly.\"}, {\"type\": \"dialogue\", \"target\": \"fall out\", \"prompt\": \"Two close friends\", \"dialogue\": [{\"speaker\": \"Amy\", \"text\": \"Are Mia and Grace still not speaking?\"}, {\"speaker\": \"Ben\", \"text\": \"No. They argued about the trip.\"}, {\"speaker\": \"Amy\", \"text\": \"They used to be so close.\"}, {\"speaker\": \"Ben\", \"text\": \"I know. They ___ over something small.\"}], \"options\": [\"take over\", \"turn down\", \"fell out\"], \"answer\": \"fell out\", \"explanation\": \"“fall out” means have an argument and stop being friendly.\"}, {\"type\": \"order\", \"target\": \"talk it out\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"out\", \"talk\"], \"answer\": \"talk it out\", \"explanation\": \"The natural phrase is “talk it out.” “talk it out” means discuss a problem until it is resolved.\"}, {\"type\": \"dialogue\", \"target\": \"count on\", \"prompt\": \"Airport ride\", \"dialogue\": [{\"speaker\": \"Ken\", \"text\": \"My flight leaves at six in the morning.\"}, {\"speaker\": \"Rosa\", \"text\": \"Do you have a ride to the airport?\"}, {\"speaker\": \"Ken\", \"text\": \"Not yet.\"}, {\"speaker\": \"Rosa\", \"text\": \"You can ___ me. I’ll drive you.\"}], \"options\": [\"take over\", \"count on\", \"turn down\"], \"answer\": \"count on\", \"explanation\": \"“count on” means depend on someone.\"}]\n```\n","content/anne-of-green-gables/chapter-13.md":"# Chapter 13 — The Delights of Anticipation\n\n## Story Summary — A2–B1 Level\n\nAnne learns that the Sunday school is planning a picnic. She has never attended a real picnic before, and the thought fills her with excitement. The most exciting detail is that ice cream will be served.\n\nAnne has never tasted it and imagines how wonderful it will be. She tells Marilla that looking forward to something can be almost as enjoyable as the event itself. Marilla agrees to let Anne go and promises to prepare food.\n\nAnne is so grateful that she hugs and kisses Marilla. Marilla is embarrassed but secretly pleased. Anne spends the following days thinking about the picnic and hoping that nothing will prevent her from attending.\n\nAn ordinary community event becomes something wonderful through Anne's ability to anticipate happiness.\n\n## Conversation 1 — The Picnic\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I can't stop looking forward to the picnic.\nMarilla: Don't let it get in the way of your chores.\nAnne: I'll catch up on everything.\n\n### Phrasal Verbs\n\n- look forward to — feel excited about a future event.\n- get in the way of — interfere with something.\n- catch up on — complete work you have not finished.\n\n## Conversation 2 — Waiting\n\n*A modern conversation inspired by this chapter.*\n\nDiana: What if it rains?\nAnne: Don't bring that up!\nDiana: All right. We'll hope for good weather.\n\n### Useful Expressions\n\n- bring up — start talking about a subject.\n- hope for — want something good to happen.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"look forward to\", \"prompt\": \"Which expression best means “feel excited about a future event”?\", \"options\": [\"take over\", \"look forward to\", \"turn down\"], \"answer\": \"look forward to\", \"explanation\": \"“look forward to” means feel excited about a future event.\"}, {\"type\": \"fill\", \"target\": \"get in the way of\", \"prompt\": \"Complete the expression: “get in the way ___”\", \"answer\": \"of\", \"accepted\": [\"of\"], \"explanation\": \"The complete expression is “get in the way of,” meaning interfere with something.\"}, {\"type\": \"dialogue\", \"target\": \"catch up on\", \"prompt\": \"A quiet weekend\", \"dialogue\": [{\"speaker\": \"Leo\", \"text\": \"Any plans this weekend?\"}, {\"speaker\": \"Mara\", \"text\": \"Nothing exciting.\"}, {\"speaker\": \"Leo\", \"text\": \"That can be nice.\"}, {\"speaker\": \"Mara\", \"text\": \"Exactly. I’m going to ___ some sleep and laundry.\"}], \"options\": [\"turn down\", \"catch up on\", \"take over\"], \"answer\": \"catch up on\", \"explanation\": \"“catch up on” means complete work you have not finished.\"}, {\"type\": \"order\", \"target\": \"bring up\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"up\", \"bring\"], \"answer\": \"bring it up\", \"explanation\": \"The natural phrase is “bring it up.” “bring up” means start talking about a subject.\"}, {\"type\": \"dialogue\", \"target\": \"hope for\", \"prompt\": \"Waiting for test results\", \"dialogue\": [{\"speaker\": \"Nia\", \"text\": \"When do you get the results?\"}, {\"speaker\": \"Eric\", \"text\": \"Tomorrow afternoon.\"}, {\"speaker\": \"Nia\", \"text\": \"Are you nervous?\"}, {\"speaker\": \"Eric\", \"text\": \"A little. I’m just ___ good news.\"}], \"options\": [\"take over\", \"hoping for\", \"turn down\"], \"answer\": \"hoping for\", \"explanation\": \"“hope for” means want something good to happen.\"}]\n```\n","content/anne-of-green-gables/chapter-14.md":"# Chapter 14 — Anne's Confession\n\n## Story Summary — A2–B1 Level\n\nJust before the picnic, Marilla cannot find her amethyst brooch. Anne had admired it, so Marilla asks whether she touched it. Anne admits trying it on but says she put it back.\n\nMarilla does not believe her and says Anne cannot attend the picnic until she confesses. Desperate to go, Anne invents a confession. She says she took the brooch outside and accidentally lost it in the water.\n\nThen Marilla discovers the brooch caught on her own shawl. Anne had told the truth at first. Marilla realizes she pressured Anne into confessing to something she did not do. Anne explains that she invented the story because she thought a confession was the only way to get permission to attend the picnic.\n\nMarilla apologizes and lets her go. Both learn a lesson: adults can make unfair assumptions, and Anne's imagination can create trouble when an invented story is presented as fact.\n\n## Conversation 1 — The Missing Brooch\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: The brooch has gone missing.\nAnne: I put it back.\nMarilla: We need to figure this out.\n\n### Phrasal Verbs\n\n- go missing — become lost or disappear.\n- figure out — understand or solve something.\n\n## Conversation 2 — The Truth\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: The brooch turned up on my shawl.\nAnne: Then you know I told the truth.\nMarilla: I jumped to conclusions. I should have listened.\n\n### Useful Expressions\n\n- turn up — be found unexpectedly.\n- jump to conclusions — decide too quickly without enough facts.\n\n- miss out on — lose the chance to experience or do something. I don’t want to miss out on the picnic.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"go missing\", \"prompt\": \"Which expression best means “become lost or disappear”?\", \"options\": [\"take over\", \"go missing\", \"turn down\"], \"answer\": \"go missing\", \"explanation\": \"“go missing” means become lost or disappear.\"}, {\"type\": \"fill\", \"target\": \"figure out\", \"prompt\": \"Complete the expression: “figure ___”\", \"answer\": \"out\", \"accepted\": [\"out\"], \"explanation\": \"The complete expression is “figure out,” meaning understand or solve something.\"}, {\"type\": \"dialogue\", \"target\": \"turn up\", \"prompt\": \"Missing keys\", \"dialogue\": [{\"speaker\": \"Sam\", \"text\": \"I still can’t find my keys.\"}, {\"speaker\": \"Lena\", \"text\": \"Did you check your coat pocket?\"}, {\"speaker\": \"Sam\", \"text\": \"Three times.\"}, {\"speaker\": \"Lena\", \"text\": \"Don’t worry. They usually ___ somewhere obvious.\"}], \"options\": [\"turn up\", \"take over\", \"turn down\"], \"answer\": \"turn up\", \"explanation\": \"“turn up” means be found unexpectedly.\"}, {\"type\": \"order\", \"target\": \"jump to conclusions\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"to\", \"conclusions\", \"jump\"], \"answer\": \"jump to conclusions\", \"explanation\": \"The natural phrase is “jump to conclusions.” “jump to conclusions” means decide too quickly without enough facts.\"}, {\"type\": \"dialogue\", \"target\": \"miss out on\", \"prompt\": \"A sold-out event\", \"dialogue\": [{\"speaker\": \"Ari\", \"text\": \"Did you buy tickets for the food festival?\"}, {\"speaker\": \"Kim\", \"text\": \"Not yet.\"}, {\"speaker\": \"Ari\", \"text\": \"They’re almost sold out.\"}, {\"speaker\": \"Kim\", \"text\": \"Then I’d better book now. I don’t want to ___ it.\"}], \"options\": [\"take over\", \"miss out on\", \"turn down\"], \"answer\": \"miss out on\", \"explanation\": \"“miss out on” means lose the chance to experience or do something.\"}]\n```\n","content/anne-of-green-gables/chapter-15.md":"# Chapter 15 — A Tempest in the School Teapot\n\n## Story Summary — A2–B1 Level\n\nAnne begins attending Avonlea school and enjoys studying with Diana and the other girls. Then Gilbert Blythe returns. He is confident and popular. When Anne ignores him, Gilbert pulls her braid and calls her \"Carrots,\" teasing her about her red hair.\n\nAnne is furious and breaks her slate over his head. Mr. Phillips punishes her and later makes her sit beside Gilbert, making her humiliation worse. Gilbert apologizes, but Anne refuses to forgive him.\n\nShe decides he will be her enemy. Anne becomes so upset that she refuses to return to school for a time. This event begins a long rivalry. Gilbert is interested in Anne, but Anne's pride and sensitivity turn their first meeting into a lasting conflict.\n\n## Conversation 1 — At School\n\n*A modern conversation inspired by this chapter.*\n\nDiana: Why did you go after Gilbert?\nAnne: He made fun of my hair.\nDiana: He was teasing.\nAnne: I won't put up with that.\n\n### Phrasal Verbs\n\n- go after — confront or pursue someone.\n- make fun of — laugh at someone unkindly.\n- put up with — accept something unpleasant.\n\n## Conversation 2 — Cooling Off\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: You need to cool off.\nAnne: I'm not going back.\nMarilla: In time, you may get over it.\n\n### Useful Expressions\n\n- cool off — become less angry.\n- get over — recover emotionally from something.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"go after\", \"prompt\": \"Which expression best means “confront or pursue someone”?\", \"options\": [\"take over\", \"go after\", \"turn down\"], \"answer\": \"go after\", \"explanation\": \"“go after” means confront or pursue someone.\"}, {\"type\": \"fill\", \"target\": \"make fun of\", \"prompt\": \"Complete the expression: “make fun ___”\", \"answer\": \"of\", \"accepted\": [\"of\"], \"explanation\": \"The complete expression is “make fun of,” meaning laugh at someone unkindly.\"}, {\"type\": \"dialogue\", \"target\": \"put up with\", \"prompt\": \"A noisy neighbor\", \"dialogue\": [{\"speaker\": \"Liam\", \"text\": \"Did the upstairs neighbors have another party?\"}, {\"speaker\": \"Nora\", \"text\": \"Yes, until two in the morning.\"}, {\"speaker\": \"Liam\", \"text\": \"That’s the third time this month.\"}, {\"speaker\": \"Nora\", \"text\": \"I can’t ___ the noise much longer.\"}], \"options\": [\"take over\", \"turn down\", \"put up with\"], \"answer\": \"put up with\", \"explanation\": \"“put up with” means accept something unpleasant.\"}, {\"type\": \"order\", \"target\": \"cool off\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"off\", \"cool\"], \"answer\": \"cool off\", \"explanation\": \"The natural phrase is “cool off.” “cool off” means become less angry.\"}, {\"type\": \"dialogue\", \"target\": \"get over\", \"prompt\": \"A bad cold\", \"dialogue\": [{\"speaker\": \"Jen\", \"text\": \"You sound much better today.\"}, {\"speaker\": \"Cole\", \"text\": \"Thanks. I finally slept well last night.\"}, {\"speaker\": \"Jen\", \"text\": \"So the cold is almost gone?\"}, {\"speaker\": \"Cole\", \"text\": \"Yes, I think I’m finally ___ it.\"}], \"options\": [\"take over\", \"getting over\", \"turn down\"], \"answer\": \"getting over\", \"explanation\": \"“get over” means recover emotionally from something.\"}]\n```\n","content/anne-of-green-gables/chapter-16.md":"# Chapter 16 — Diana Is Invited to Tea with Tragic Results\n\n## Story Summary — A2–B1 Level\n\nMarilla leaves Anne in charge of Green Gables for a day and allows her to invite Diana to tea. Anne is delighted and wants everything to feel grown-up and elegant. Anne believes she is serving raspberry cordial.\n\nDiana likes it and drinks several glasses. Soon she becomes dizzy and unwell. The drink was actually currant wine. Anne had taken the wrong bottle without realizing it.\n\nMrs. Barry is furious. Although Anne explains that it was an innocent mistake, Mrs. Barry forbids Diana from spending time with her. Anne is heartbroken. Losing Diana feels like a terrible tragedy. Marilla knows Anne is innocent and defends her, but Mrs. Barry refuses to change her mind.\n\n## Conversation 1 — Something Is Wrong\n\n*A modern conversation inspired by this chapter.*\n\nAnne: Maybe you should lie down.\nDiana: I think I need to go home.\nAnne: I'll walk you back.\n\n### Phrasal Verbs\n\n- lie down — put your body in a resting position.\n- go home — return home.\n- walk someone back — walk with someone to where they came from.\n\n## Conversation 2 — Mrs. Barry Is Angry\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I mixed up the bottles.\nMrs. Barry: Diana won't be coming over anymore.\nAnne: Please don't keep us apart.\n\n### Useful Expressions\n\n- mix up — confuse one thing with another.\n- come over — visit someone's home.\n- keep apart — prevent people from being together.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"lie down\", \"prompt\": \"Which expression best means “put your body in a resting position”?\", \"options\": [\"take over\", \"lie down\", \"turn down\"], \"answer\": \"lie down\", \"explanation\": \"“lie down” means put your body in a resting position.\"}, {\"type\": \"fill\", \"target\": \"go home\", \"prompt\": \"Complete the expression: “go ___”\", \"answer\": \"home\", \"accepted\": [\"home\"], \"explanation\": \"The complete expression is “go home,” meaning return home.\"}, {\"type\": \"dialogue\", \"target\": \"walk someone back\", \"prompt\": \"After dinner\", \"dialogue\": [{\"speaker\": \"Lina\", \"text\": \"It’s getting late.\"}, {\"speaker\": \"Omar\", \"text\": \"And it’s pretty dark outside.\"}, {\"speaker\": \"Lina\", \"text\": \"I only live two blocks away.\"}, {\"speaker\": \"Omar\", \"text\": \"I know, but I’ll ___ to your building.\"}], \"options\": [\"turn down\", \"walk you back\", \"take over\"], \"answer\": \"walk you back\", \"explanation\": \"“walk someone back” means walk with someone to where they came from.\"}, {\"type\": \"order\", \"target\": \"mix up\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"them\", \"up\", \"mix\"], \"answer\": \"mix them up\", \"explanation\": \"The natural phrase is “mix them up.” “mix up” means confuse one thing with another.\"}, {\"type\": \"dialogue\", \"target\": \"come over\", \"prompt\": \"Weekend coffee\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"Are you free Saturday afternoon?\"}, {\"speaker\": \"Alex\", \"text\": \"Yes. Why?\"}, {\"speaker\": \"Mia\", \"text\": \"I made too much cake.\"}, {\"speaker\": \"Alex\", \"text\": \"In that case, I’ll ___ around three.\"}], \"options\": [\"take over\", \"come over\", \"turn down\"], \"answer\": \"come over\", \"explanation\": \"“come over” means visit someone's home.\"}]\n```\n","content/anne-of-green-gables/chapter-17.md":"# Chapter 17 — A New Interest in Life\n\n## Story Summary — A2–B1 Level\n\nDiana secretly visits Anne to say that her mother still refuses to let them spend time together. The girls have an emotional goodbye. Anne is miserable, but she decides to return to school because at least she can see Diana there. Her classmates welcome her back warmly. School gives Anne a new purpose.\n\nShe becomes especially interested in competing with Gilbert academically. Both are intelligent and ambitious, and the rivalry pushes Anne to work harder. Anne discovers that disappointment does not have to stop her life.\n\nShe still misses Diana outside school, but learning and competition give her new motivation.\n\n## Conversation 1 — Going Back\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I've decided to go back to school.\nMarilla: Good.\nAnne: I need something to take my mind off Diana.\nMarilla: And don't fall behind in your lessons.\n\n### Phrasal Verbs\n\n- go back to — return to a place or activity.\n- take your mind off — stop thinking about something upsetting.\n- fall behind — fail to stay at the same level.\n\n## Conversation 2 — Competition\n\n*A modern conversation inspired by this chapter.*\n\nDiana: You and Gilbert always try to outdo each other.\nAnne: He makes me work harder.\nDiana: Maybe someday you'll make up with him.\n\n### Useful Expressions\n\n- outdo — do better than someone else.\n- make up with — become friendly again.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"go back to\", \"prompt\": \"Which expression best means “return to a place or activity”?\", \"options\": [\"take over\", \"go back to\", \"turn down\"], \"answer\": \"go back to\", \"explanation\": \"“go back to” means return to a place or activity.\"}, {\"type\": \"fill\", \"target\": \"take your mind off\", \"prompt\": \"Complete the expression: “take your mind ___”\", \"answer\": \"off\", \"accepted\": [\"off\"], \"explanation\": \"The complete expression is “take your mind off,” meaning stop thinking about something upsetting.\"}, {\"type\": \"dialogue\", \"target\": \"fall behind\", \"prompt\": \"An online class\", \"dialogue\": [{\"speaker\": \"Ella\", \"text\": \"How is your online course going?\"}, {\"speaker\": \"Jon\", \"text\": \"I missed two lessons while I was sick.\"}, {\"speaker\": \"Ella\", \"text\": \"Can you catch up this weekend?\"}, {\"speaker\": \"Jon\", \"text\": \"I hope so. I don’t want to ___ any further.\"}], \"options\": [\"fall behind\", \"take over\", \"turn down\"], \"answer\": \"fall behind\", \"explanation\": \"“fall behind” means fail to stay at the same level.\"}, {\"type\": \"order\", \"target\": \"outdo\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"the\", \"competition\", \"outdo\"], \"answer\": \"outdo the competition\", \"explanation\": \"The natural phrase is “outdo the competition.” “outdo” means do better than someone else.\"}, {\"type\": \"dialogue\", \"target\": \"make up with\", \"prompt\": \"After an argument\", \"dialogue\": [{\"speaker\": \"Nora\", \"text\": \"Are you still upset with Maya?\"}, {\"speaker\": \"June\", \"text\": \"A little, but I miss talking to her.\"}, {\"speaker\": \"Nora\", \"text\": \"Maybe call her tonight.\"}, {\"speaker\": \"June\", \"text\": \"You’re right. I want to ___ her.\"}], \"options\": [\"take over\", \"make up with\", \"turn down\"], \"answer\": \"make up with\", \"explanation\": \"“make up with” means become friendly again.\"}]\n```\n","content/anne-of-green-gables/chapter-18.md":"# Chapter 18 — Anne to the Rescue\n\n## Story Summary — A2–B1 Level\n\nOne winter evening, Diana arrives at Green Gables in a panic. Her little sister Minnie May is seriously ill with croup, and the adults who normally care for her are away. Anne immediately goes to the Barry home.\n\nBecause she once cared for Mrs. Hammond's children, she recognizes the illness and knows what to do. Anne stays calm and cares for Minnie May until the doctor arrives. The doctor later says that Anne's quick action probably saved the child's life.\n\nMrs. Barry is deeply grateful. She realizes she judged Anne too harshly after the wine accident and allows Anne and Diana to be friends again. Anne's difficult childhood has unexpectedly given her useful knowledge. Avonlea begins to see her not simply as a strange orphan who makes mistakes, but as a capable and courageous girl.\n\n## Conversation 1 — An Emergency\n\n*A modern conversation inspired by this chapter.*\n\nDiana: Can you come over right now?\nAnne: Yes. We need to stay calm and look after Minnie May.\nDiana: Thank you.\n\n### Phrasal Verbs\n\n- come over — come to someone's home.\n- stay calm — remain calm in a difficult situation.\n- look after — take care of.\n\n## Conversation 2 — Mrs. Barry Changes Her Mind\n\n*A modern conversation inspired by this chapter.*\n\nMrs. Barry: You've proved yourself.\nAnne: Can Diana and I get together again?\nMrs. Barry: Yes. I'm glad everything worked out.\n\n### Useful Expressions\n\n- prove yourself — show that you are capable or trustworthy.\n- get together — meet and spend time together.\n- work out — end successfully.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"come over\", \"prompt\": \"Which expression best means “come to someone's home”?\", \"options\": [\"take over\", \"come over\", \"turn down\"], \"answer\": \"come over\", \"explanation\": \"“come over” means come to someone's home.\"}, {\"type\": \"fill\", \"target\": \"stay calm\", \"prompt\": \"Complete the expression: “stay ___”\", \"answer\": \"calm\", \"accepted\": [\"calm\"], \"explanation\": \"The complete expression is “stay calm,” meaning remain calm in a difficult situation.\"}, {\"type\": \"dialogue\", \"target\": \"look after\", \"prompt\": \"A friend’s plants\", \"dialogue\": [{\"speaker\": \"Eva\", \"text\": \"I’m away for ten days next month.\"}, {\"speaker\": \"Jon\", \"text\": \"Sounds nice.\"}, {\"speaker\": \"Eva\", \"text\": \"I’m worried my plants will dry out.\"}, {\"speaker\": \"Jon\", \"text\": \"I can ___ them while you’re gone.\"}], \"options\": [\"take over\", \"turn down\", \"look after\"], \"answer\": \"look after\", \"explanation\": \"“look after” means take care of.\"}, {\"type\": \"order\", \"target\": \"prove yourself\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"yourself\", \"prove\"], \"answer\": \"prove yourself\", \"explanation\": \"The natural phrase is “prove yourself.” “prove yourself” means show that you are capable or trustworthy.\"}, {\"type\": \"dialogue\", \"target\": \"get together\", \"prompt\": \"Old friends\", \"dialogue\": [{\"speaker\": \"Sara\", \"text\": \"We haven’t seen Daniel and Kim in months.\"}, {\"speaker\": \"Tom\", \"text\": \"Everyone has been so busy.\"}, {\"speaker\": \"Sara\", \"text\": \"We should plan something.\"}, {\"speaker\": \"Tom\", \"text\": \"Definitely. Let’s ___ for dinner next Friday.\"}], \"options\": [\"take over\", \"get together\", \"turn down\"], \"answer\": \"get together\", \"explanation\": \"“get together” means meet and spend time together.\"}]\n```\n","content/anne-of-green-gables/chapter-19.md":"# Chapter 19 — A Concert, a Catastrophe, and a Confession\n\n## Story Summary — A2–B1 Level\n\nAnne and Diana attend a concert and later stay at Diana's house while Mr. and Mrs. Barry are away. For fun, the girls race into the spare room and jump onto the bed. Unfortunately, Diana's elderly Aunt Josephine has arrived unexpectedly and is already sleeping there.\n\nAunt Josephine is furious and threatens to leave. Diana worries because her aunt has always been generous to the family. Anne feels responsible and apologizes sincerely.\n\nInstead of making a dramatic performance, she honestly explains what happened. Aunt Josephine is amused by Anne's personality and forgives the girls. The accident creates a new friendship, and Anne's sincere apology shows that she is becoming more mature.\n\n## Conversation 1 — A Terrible Surprise\n\n*A modern conversation inspired by this chapter.*\n\nAnne: We really messed up.\nDiana: She wants to leave tomorrow.\nAnne: I'll own up to what we did.\n\n### Phrasal Verbs\n\n- mess up — make a mistake.\n- own up to — admit responsibility.\n\n## Conversation 2 — The Apology\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I hope you can forgive us.\nAunt Josephine: At least you came forward and apologized.\nAnne: Can we put it behind us?\nAunt Josephine: Yes.\n\n### Useful Expressions\n\n- come forward — present yourself to give information or accept responsibility.\n- put something behind you — stop focusing on a past problem.\n\n- wake someone up — cause someone who is sleeping to become awake. Please don’t wake the baby up.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"mess up\", \"prompt\": \"Which expression best means “make a mistake”?\", \"options\": [\"take over\", \"mess up\", \"turn down\"], \"answer\": \"mess up\", \"explanation\": \"“mess up” means make a mistake.\"}, {\"type\": \"fill\", \"target\": \"own up to\", \"prompt\": \"Complete the expression: “own up ___”\", \"answer\": \"to\", \"accepted\": [\"to\"], \"explanation\": \"The complete expression is “own up to,” meaning admit responsibility.\"}, {\"type\": \"dialogue\", \"target\": \"come forward\", \"prompt\": \"A lost wallet\", \"dialogue\": [{\"speaker\": \"Clerk\", \"text\": \"Someone left a wallet near the register.\"}, {\"speaker\": \"Manager\", \"text\": \"Do we know who found it?\"}, {\"speaker\": \"Clerk\", \"text\": \"Not yet.\"}, {\"speaker\": \"Manager\", \"text\": \"Hopefully the person who saw what happened will ___ and tell us.\"}], \"options\": [\"turn down\", \"come forward\", \"take over\"], \"answer\": \"come forward\", \"explanation\": \"“come forward” means present yourself to give information or accept responsibility.\"}, {\"type\": \"order\", \"target\": \"put something behind you\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"behind\", \"you\", \"put\"], \"answer\": \"put it behind you\", \"explanation\": \"The natural phrase is “put it behind you.” “put something behind you” means stop focusing on a past problem.\"}, {\"type\": \"dialogue\", \"target\": \"wake someone up\", \"prompt\": \"An early morning\", \"dialogue\": [{\"speaker\": \"Mina\", \"text\": \"Why are you whispering?\"}, {\"speaker\": \"Jack\", \"text\": \"The baby finally fell asleep.\"}, {\"speaker\": \"Mina\", \"text\": \"Oh, I’ll close the door quietly.\"}, {\"speaker\": \"Jack\", \"text\": \"Thanks. I really don’t want to ___ him.\"}], \"options\": [\"take over\", \"wake up\", \"turn down\"], \"answer\": \"wake up\", \"explanation\": \"“wake someone up” means cause someone who is sleeping to become awake.\"}]\n```\n","content/anne-of-green-gables/chapter-20.md":"# Chapter 20 — A Good Imagination Gone Wrong\n\n## Story Summary — A2–B1 Level\n\nSpring returns, and Anne happily explores the countryside with her friends. She and Diana use their imaginations to make ordinary places more exciting. They invent frightening stories about a wooded area between their homes and begin calling it haunted.\n\nAfter repeating the stories, Anne starts to feel genuinely afraid. One evening, Marilla sends Anne through the woods on an errand. Anne begs to wait until morning, but Marilla insists that she go.\n\nAnne runs through the woods in terror and returns safely. She realizes that she and Diana allowed their imagination to go too far. Anne does not lose her imagination, but she learns that it should add beauty to life rather than create unnecessary fear.\n\n## Conversation 1 — The Haunted Wood\n\n*A modern conversation inspired by this chapter.*\n\nAnne: Diana and I made up ghost stories.\nMarilla: And now they're getting to you.\nAnne: I don't want to go through the woods.\n\n### Phrasal Verbs\n\n- make up — invent.\n- get to someone — begin to upset someone.\n- go through — travel through a place.\n\n## Conversation 2 — Afterward\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: You made it through.\nAnne: Barely!\nMarilla: Maybe you'll cut back on ghost stories.\nAnne: We definitely went too far.\n\n### Useful Expressions\n\n- make it through — successfully survive or complete something.\n- cut back on — reduce.\n- go too far — do more than is reasonable.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"make up\", \"prompt\": \"Which expression best means “invent”?\", \"options\": [\"take over\", \"make up\", \"turn down\"], \"answer\": \"make up\", \"explanation\": \"“make up” means invent.\"}, {\"type\": \"fill\", \"target\": \"get to someone\", \"prompt\": \"Complete the expression: “get to ___”\", \"answer\": \"someone\", \"accepted\": [\"someone\"], \"explanation\": \"The complete expression is “get to someone,” meaning begin to upset someone.\"}, {\"type\": \"dialogue\", \"target\": \"go through\", \"prompt\": \"A security check\", \"dialogue\": [{\"speaker\": \"Nina\", \"text\": \"Why did it take so long to enter the building?\"}, {\"speaker\": \"Owen\", \"text\": \"Security was checking every bag.\"}, {\"speaker\": \"Nina\", \"text\": \"Did they check yours too?\"}, {\"speaker\": \"Owen\", \"text\": \"Yes, everyone had to ___ the same process.\"}], \"options\": [\"go through\", \"take over\", \"turn down\"], \"answer\": \"go through\", \"explanation\": \"“go through” means travel through a place.\"}, {\"type\": \"order\", \"target\": \"make it through\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"through\", \"make\"], \"answer\": \"make it through\", \"explanation\": \"The natural phrase is “make it through.” “make it through” means successfully survive or complete something.\"}, {\"type\": \"dialogue\", \"target\": \"cut back on\", \"prompt\": \"A healthier routine\", \"dialogue\": [{\"speaker\": \"Jae\", \"text\": \"Why did you skip the second coffee?\"}, {\"speaker\": \"Mila\", \"text\": \"I haven’t been sleeping well.\"}, {\"speaker\": \"Jae\", \"text\": \"So you’re avoiding caffeine?\"}, {\"speaker\": \"Mila\", \"text\": \"I’m trying to ___ it after lunch.\"}], \"options\": [\"take over\", \"cut back on\", \"turn down\"], \"answer\": \"cut back on\", \"explanation\": \"“cut back on” means reduce.\"}]\n```\n","content/anne-of-green-gables/chapter-21.md":"# Chapter 21 — A New Departure in Flavorings\n\n## Story Summary — A2–B1 Level\n\nAvonlea goes through several changes. Mr. Phillips leaves the school, and a young minister, Mr. Allan, and his wife come to the community. Anne immediately admires Mrs. Allan because she is warm and encourages children to ask questions. Marilla invites the Allans to tea. Anne is allowed to bake a special layer cake and wants desperately to impress Mrs. Allan.\n\nUnfortunately, Anne accidentally uses anodyne liniment instead of vanilla flavoring. The cake tastes terrible. Anne believes she has ruined the visit. Mrs. Allan treats the mistake kindly, which makes Anne admire her even more.\n\nSoon Anne also learns that a new teacher, Miss Stacy, will come to Avonlea, bringing another important change.\n\n## Conversation 1 — The Cake\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: What did you put in the cake?\nAnne: I thought I picked up the vanilla.\nMarilla: This is liniment!\n\n### Phrasal Verbs\n\n- put in — add something.\n- pick up — take or choose something.\n\n## Conversation 2 — Mrs. Allan's Reaction\n\n*A modern conversation inspired by this chapter.*\n\nMrs. Allan: Don't beat yourself up over a cake.\nAnne: I wanted it to be perfect.\nMrs. Allan: Let's move on and enjoy the afternoon.\n\n### Useful Expressions\n\n- beat yourself up — criticize yourself too harshly.\n- move on — stop focusing on a problem and continue.\n\n- end up — finally be in a particular situation, often unexpectedly. We ended up eating dinner much later than planned.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"put in\", \"prompt\": \"Which expression best means “add something”?\", \"options\": [\"take over\", \"put in\", \"turn down\"], \"answer\": \"put in\", \"explanation\": \"“put in” means add something.\"}, {\"type\": \"fill\", \"target\": \"pick up\", \"prompt\": \"Complete the expression: “pick ___”\", \"answer\": \"up\", \"accepted\": [\"up\"], \"explanation\": \"The complete expression is “pick up,” meaning take or choose something.\"}, {\"type\": \"dialogue\", \"target\": \"beat yourself up\", \"prompt\": \"A small mistake\", \"dialogue\": [{\"speaker\": \"Ana\", \"text\": \"I sent the email with the wrong attachment.\"}, {\"speaker\": \"Ben\", \"text\": \"It happens.\"}, {\"speaker\": \"Ana\", \"text\": \"I feel terrible about it.\"}, {\"speaker\": \"Ben\", \"text\": \"Don’t ___ over one small mistake.\"}], \"options\": [\"take over\", \"turn down\", \"beat yourself up\"], \"answer\": \"beat yourself up\", \"explanation\": \"“beat yourself up” means criticize yourself too harshly.\"}, {\"type\": \"order\", \"target\": \"move on\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"on\", \"move\"], \"answer\": \"move on\", \"explanation\": \"The natural phrase is “move on.” “move on” means stop focusing on a problem and continue.\"}, {\"type\": \"dialogue\", \"target\": \"end up\", \"prompt\": \"A changed evening plan\", \"dialogue\": [{\"speaker\": \"Owen\", \"text\": \"Did you go to the outdoor concert?\"}, {\"speaker\": \"Lily\", \"text\": \"No, it started raining.\"}, {\"speaker\": \"Owen\", \"text\": \"So what did you do instead?\"}, {\"speaker\": \"Lily\", \"text\": \"We ___ watching a movie at home.\"}], \"options\": [\"take over\", \"ended up\", \"turn down\"], \"answer\": \"ended up\", \"explanation\": \"“end up” means finally be in a particular situation, often unexpectedly.\"}]\n```\n","content/anne-of-green-gables/chapter-22.md":"# Chapter 22 — Anne Is Invited Out to Tea\n\n## Story Summary — A2–B1 Level\n\nMrs. Allan invites Anne to tea at the manse. Anne is extremely excited because she admires Mrs. Allan and considers the invitation a great honor. Before going, Anne worries about how she should behave.\n\nMarilla reminds her to use good manners and not talk too much. At the manse, Mrs. Allan makes Anne feel comfortable. They talk naturally, and Anne discovers that visiting an adult can be enjoyable rather than frightening.\n\nMrs. Allan treats Anne with respect and genuine interest. Anne returns home feeling that the afternoon was one of the happiest of her life. The visit is important because Anne is forming relationships with adults outside Green Gables.\n\nMrs. Allan becomes a positive influence who understands Anne's imagination.\n\n## Conversation 1 — Before Tea\n\n*A modern conversation inspired by this chapter.*\n\nAnne: What if I say the wrong thing?\nMarilla: Don't work yourself up.\nAnne: I'll try not to go on and on.\n\n### Phrasal Verbs\n\n- work yourself up — make yourself increasingly worried.\n- go on and on — talk for a long time.\n\n## Conversation 2 — After the Visit\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: How did you get on?\nAnne: Mrs. Allan made me feel at home.\nMarilla: You weren't nervous?\nAnne: Not after we got talking.\n\n### Useful Expressions\n\n- get on — manage or progress.\n- feel at home — feel comfortable.\n- get talking — begin a conversation.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"work yourself up\", \"prompt\": \"Which expression best means “make yourself increasingly worried”?\", \"options\": [\"take over\", \"work yourself up\", \"turn down\"], \"answer\": \"work yourself up\", \"explanation\": \"“work yourself up” means make yourself increasingly worried.\"}, {\"type\": \"fill\", \"target\": \"go on and on\", \"prompt\": \"Complete the expression: “go on and ___”\", \"answer\": \"on\", \"accepted\": [\"on\"], \"explanation\": \"The complete expression is “go on and on,” meaning talk for a long time.\"}, {\"type\": \"dialogue\", \"target\": \"get on\", \"prompt\": \"A first date\", \"dialogue\": [{\"speaker\": \"Maya\", \"text\": \"How was your coffee date?\"}, {\"speaker\": \"Leo\", \"text\": \"Really nice. We talked for almost three hours.\"}, {\"speaker\": \"Maya\", \"text\": \"So you two connected?\"}, {\"speaker\": \"Leo\", \"text\": \"Yes, we ___ really well.\"}], \"options\": [\"turn down\", \"got on\", \"take over\"], \"answer\": \"got on\", \"explanation\": \"“get on” means manage or progress.\"}, {\"type\": \"order\", \"target\": \"feel at home\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"at\", \"home\", \"feel\"], \"answer\": \"feel at home\", \"explanation\": \"The natural phrase is “feel at home.” “feel at home” means feel comfortable.\"}, {\"type\": \"dialogue\", \"target\": \"get talking\", \"prompt\": \"At a conference\", \"dialogue\": [{\"speaker\": \"Noah\", \"text\": \"Did you know anyone at the conference?\"}, {\"speaker\": \"Eva\", \"text\": \"No, but I sat next to someone from Boston.\"}, {\"speaker\": \"Noah\", \"text\": \"Was it awkward?\"}, {\"speaker\": \"Eva\", \"text\": \"Not at all. We ___ and discovered we work in the same field.\"}], \"options\": [\"take over\", \"got talking\", \"turn down\"], \"answer\": \"got talking\", \"explanation\": \"“get talking” means begin a conversation.\"}]\n```\n","content/anne-of-green-gables/chapter-23.md":"# Chapter 23 — Anne Comes to Grief in an Affair of Honor\n\n## Story Summary — A2–B1 Level\n\nAnne's friends sometimes dare one another to prove their courage. One day, Josie Pye challenges Anne to walk along the ridgepole of a kitchen roof. Anne does not want to do it, but she is proud and does not want the others to think she is afraid.\n\nShe climbs onto the roof. Anne loses her balance and falls. She survives but breaks her ankle and must spend several weeks recovering. Marilla is frightened and angry that Anne took such a foolish risk because of a dare.\n\nWhile recovering, Anne realizes that trying to prove courage is not the same as showing real courage. The accident becomes another lesson about pride and impulsive decisions.\n\n## Conversation 1 — The Dare\n\n*A modern conversation inspired by this chapter.*\n\nJosie: Are you going to back down?\nAnne: No. I'll go through with it.\nDiana: Don't give in to a foolish dare.\n\n### Phrasal Verbs\n\n- back down — stop accepting a challenge.\n- go through with — do something despite difficulty.\n- give in to — allow pressure to control you.\n\n## Conversation 2 — Recovering\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I should have thought it through.\nMarilla: I hope you learned your lesson.\nAnne: It'll take time to get back on my feet.\n\n### Useful Expressions\n\n- think through — consider the possible results carefully.\n- get back on your feet — recover after illness, injury, or difficulty.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"back down\", \"prompt\": \"Which expression best means “stop accepting a challenge”?\", \"options\": [\"take over\", \"back down\", \"turn down\"], \"answer\": \"back down\", \"explanation\": \"“back down” means stop accepting a challenge.\"}, {\"type\": \"fill\", \"target\": \"go through with\", \"prompt\": \"Complete the expression: “go through ___”\", \"answer\": \"with\", \"accepted\": [\"with\"], \"explanation\": \"The complete expression is “go through with,” meaning do something despite difficulty.\"}, {\"type\": \"dialogue\", \"target\": \"give in to\", \"prompt\": \"A dessert temptation\", \"dialogue\": [{\"speaker\": \"Lina\", \"text\": \"I thought you were skipping dessert this week.\"}, {\"speaker\": \"Marc\", \"text\": \"I was.\"}, {\"speaker\": \"Lina\", \"text\": \"Then what happened to that piece of cake?\"}, {\"speaker\": \"Marc\", \"text\": \"I ___ temptation.\"}], \"options\": [\"gave in to\", \"take over\", \"turn down\"], \"answer\": \"gave in to\", \"explanation\": \"“give in to” means allow pressure to control you.\"}, {\"type\": \"order\", \"target\": \"think through\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"through\", \"think\"], \"answer\": \"think it through\", \"explanation\": \"The natural phrase is “think it through.” “think through” means consider the possible results carefully.\"}, {\"type\": \"dialogue\", \"target\": \"get back on your feet\", \"prompt\": \"After being sick\", \"dialogue\": [{\"speaker\": \"Kim\", \"text\": \"How are you feeling after the flu?\"}, {\"speaker\": \"Rob\", \"text\": \"Much better, but I still get tired easily.\"}, {\"speaker\": \"Kim\", \"text\": \"Take it slow for a few days.\"}, {\"speaker\": \"Rob\", \"text\": \"I will. I’m just trying to ___.\"}], \"options\": [\"take over\", \"get back on my feet\", \"turn down\"], \"answer\": \"get back on my feet\", \"explanation\": \"“get back on your feet” means recover after illness, injury, or difficulty.\"}]\n```\n","content/anne-of-green-gables/chapter-24.md":"# Chapter 24 — Miss Stacy and Her Pupils Get Up a Concert\n\n## Story Summary — A2–B1 Level\n\nMiss Stacy becomes Avonlea's new teacher, and Anne quickly admires her. Miss Stacy uses lively methods, encourages exercise, and makes lessons more interesting. Some adults are suspicious of her modern ideas, but the students respond enthusiastically.\n\nMiss Stacy decides that the school should organize a Christmas concert to raise money for a Canadian flag. Anne is thrilled and receives several parts, including recitations. Marilla thinks the concert creates unnecessary excitement.\n\nMatthew, however, quietly enjoys Anne's enthusiasm. Miss Stacy also recognizes Anne's intelligence and encourages her. School is beginning to shape Anne's ambitions for the future.\n\n## Conversation 1 — The Concert\n\n*A modern conversation inspired by this chapter.*\n\nAnne: We're going to put on a concert!\nMatthew: What for?\nAnne: To raise money for a flag. I'm going to throw myself\ninto it.\n\n### Phrasal Verbs\n\n- put on — organize and perform a show.\n- raise money for — collect money for a purpose.\n- throw yourself into — do something with great energy.\n\n## Conversation 2 — Rehearsal\n\n*A modern conversation inspired by this chapter.*\n\nDiana: Let's run through the program.\nAnne: I need to work on my recitation.\nDiana: You won't let Miss Stacy down.\n\n### Useful Expressions\n\n- run through — practice from beginning to end.\n- work on — spend time improving.\n- let someone down — disappoint someone.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"put on\", \"prompt\": \"Which expression best means “organize and perform a show”?\", \"options\": [\"take over\", \"put on\", \"turn down\"], \"answer\": \"put on\", \"explanation\": \"“put on” means organize and perform a show.\"}, {\"type\": \"fill\", \"target\": \"raise money for\", \"prompt\": \"Complete the expression: “raise money ___”\", \"answer\": \"for\", \"accepted\": [\"for\"], \"explanation\": \"The complete expression is “raise money for,” meaning collect money for a purpose.\"}, {\"type\": \"dialogue\", \"target\": \"throw yourself into\", \"prompt\": \"A new project\", \"dialogue\": [{\"speaker\": \"Ava\", \"text\": \"You’ve made a lot of progress on the garden.\"}, {\"speaker\": \"Ben\", \"text\": \"I had a free weekend.\"}, {\"speaker\": \"Ava\", \"text\": \"You worked on it almost nonstop.\"}, {\"speaker\": \"Ben\", \"text\": \"Once I started, I really ___ the project.\"}], \"options\": [\"take over\", \"turn down\", \"threw myself into\"], \"answer\": \"threw myself into\", \"explanation\": \"“throw yourself into” means do something with great energy.\"}, {\"type\": \"order\", \"target\": \"run through\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"through\", \"the\", \"plan\", \"run\"], \"answer\": \"run through the plan\", \"explanation\": \"The natural phrase is “run through the plan.” “run through” means practice from beginning to end.\"}, {\"type\": \"dialogue\", \"target\": \"let someone down\", \"prompt\": \"Keeping a promise\", \"dialogue\": [{\"speaker\": \"Jay\", \"text\": \"Are you still helping your sister move tomorrow?\"}, {\"speaker\": \"Mina\", \"text\": \"Yes, even though I’m tired.\"}, {\"speaker\": \"Jay\", \"text\": \"You could cancel.\"}, {\"speaker\": \"Mina\", \"text\": \"I promised her. I don’t want to ___ her.\"}], \"options\": [\"take over\", \"let down\", \"turn down\"], \"answer\": \"let down\", \"explanation\": \"“let someone down” means disappoint someone.\"}]\n```\n","content/anne-of-green-gables/chapter-25.md":"# Chapter 25 — Matthew Insists on Puffed Sleeves\n\n## Story Summary — A2–B1 Level\n\nMatthew notices that Anne's clothes are much plainer than those of her friends. He realizes that Anne especially wants a dress with fashionable puffed sleeves. Because Matthew is extremely shy around women, shopping for a dress is difficult.\n\nHe goes to a store but becomes nervous and buys several things he did not intend to buy. Eventually, he asks Mrs. Rachel Lynde for help. She offers to make Anne a beautiful brown dress with puffed sleeves.\n\nOn Christmas morning, Matthew gives the dress to Anne. She is overwhelmed with happiness. Even Marilla can see how much the gift means to her. The Christmas concert is a success, and Anne enjoys performing in her new dress.\n\nMatthew's gift shows that although he says little, he notices what matters to Anne.\n\n## Conversation 1 — Asking for Help\n\n*A modern conversation inspired by this chapter.*\n\nMatthew: I want to pick out a dress for Anne.\nMrs. Lynde: You?\nMatthew: I tried, but I got nervous.\nMrs. Lynde: I'll help you out.\n\n### Phrasal Verbs\n\n- pick out — choose.\n- get nervous — begin to feel anxious.\n- help out — give practical assistance.\n\n## Conversation 2 — Christmas Morning\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I can't get over these sleeves!\nMatthew: Do you like them?\nAnne: I'll take good care of this dress forever.\n\n### Useful Expressions\n\n- get over — stop being surprised or excited.\n- take good care of — protect and keep in good condition.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"pick out\", \"prompt\": \"Which expression best means “choose”?\", \"options\": [\"take over\", \"pick out\", \"turn down\"], \"answer\": \"pick out\", \"explanation\": \"“pick out” means choose.\"}, {\"type\": \"fill\", \"target\": \"get nervous\", \"prompt\": \"Complete the expression: “get ___”\", \"answer\": \"nervous\", \"accepted\": [\"nervous\"], \"explanation\": \"The complete expression is “get nervous,” meaning begin to feel anxious.\"}, {\"type\": \"dialogue\", \"target\": \"help out\", \"prompt\": \"A busy kitchen\", \"dialogue\": [{\"speaker\": \"Rae\", \"text\": \"Dinner is in twenty minutes and I’m behind.\"}, {\"speaker\": \"Sam\", \"text\": \"What still needs to be done?\"}, {\"speaker\": \"Rae\", \"text\": \"The salad and the table.\"}, {\"speaker\": \"Sam\", \"text\": \"I’ll ___ with the salad.\"}], \"options\": [\"turn down\", \"help out\", \"take over\"], \"answer\": \"help out\", \"explanation\": \"“help out” means give practical assistance.\"}, {\"type\": \"order\", \"target\": \"get over\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"over\", \"it\", \"get\"], \"answer\": \"get over it\", \"explanation\": \"The natural phrase is “get over it.” “get over” means stop being surprised or excited.\"}, {\"type\": \"dialogue\", \"target\": \"take good care of\", \"prompt\": \"Borrowing a camera\", \"dialogue\": [{\"speaker\": \"Nora\", \"text\": \"You can borrow my camera for the trip.\"}, {\"speaker\": \"Leo\", \"text\": \"Really? It’s expensive.\"}, {\"speaker\": \"Nora\", \"text\": \"Just keep it in the case.\"}, {\"speaker\": \"Leo\", \"text\": \"Of course. I’ll ___ it.\"}], \"options\": [\"take over\", \"take good care of\", \"turn down\"], \"answer\": \"take good care of\", \"explanation\": \"“take good care of” means protect and keep in good condition.\"}]\n```\n","content/anne-of-green-gables/chapter-26.md":"# Chapter 26 — The Story Club Is Formed\n\n## Story Summary — A2–B1 Level\n\nAnne and several friends form a story club. They agree to write original stories and read them to one another. Anne loves the idea because storytelling has always been central to her imagination.\n\nAt first, the girls write very dramatic stories filled with romance and tragedy. Marilla thinks the club is another example of Anne wasting time, but Anne argues that writing can improve their skills. Over time, Anne becomes more thoughtful about writing.\n\nShe begins to understand the difference between simply inventing dramatic events and creating a good story. Her imagination, which once caused problems, is becoming a useful talent because writing gives her a place to direct it.\n\n## Conversation 1 — Starting the Club\n\n*A modern conversation inspired by this chapter.*\n\nAnne: Let's set up a story club.\nDiana: What would we do?\nAnne: Come up with a story every week and read it out.\n\n### Phrasal Verbs\n\n- set up — organize or establish.\n- come up with — think of an idea.\n- read out — read aloud.\n\n## Conversation 2 — Improving\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I'm trying to cut down on tragic endings.\nDiana: Good idea.\nAnne: Miss Stacy says we should build on real experience.\n\n### Useful Expressions\n\n- cut down on — reduce.\n- build on — develop from an existing base.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"set up\", \"prompt\": \"Which expression best means “organize or establish”?\", \"options\": [\"take over\", \"set up\", \"turn down\"], \"answer\": \"set up\", \"explanation\": \"“set up” means organize or establish.\"}, {\"type\": \"fill\", \"target\": \"come up with\", \"prompt\": \"Complete the expression: “come up ___”\", \"answer\": \"with\", \"accepted\": [\"with\"], \"explanation\": \"The complete expression is “come up with,” meaning think of an idea.\"}, {\"type\": \"dialogue\", \"target\": \"read out\", \"prompt\": \"A team meeting\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"Did everyone see the new schedule?\"}, {\"speaker\": \"Ben\", \"text\": \"Not yet.\"}, {\"speaker\": \"Mia\", \"text\": \"I have it here.\"}, {\"speaker\": \"Ben\", \"text\": \"Could you ___ the dates for us?\"}], \"options\": [\"read out\", \"take over\", \"turn down\"], \"answer\": \"read out\", \"explanation\": \"“read out” means read aloud.\"}, {\"type\": \"order\", \"target\": \"cut down on\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"down\", \"on\", \"sugar\", \"cut\"], \"answer\": \"cut down on sugar\", \"explanation\": \"The natural phrase is “cut down on sugar.” “cut down on” means reduce.\"}, {\"type\": \"dialogue\", \"target\": \"build on\", \"prompt\": \"Improving an idea\", \"dialogue\": [{\"speaker\": \"Lena\", \"text\": \"Your first presentation was strong.\"}, {\"speaker\": \"Owen\", \"text\": \"Thanks. I want the next one to be even better.\"}, {\"speaker\": \"Lena\", \"text\": \"Keep the clear opening and add more examples.\"}, {\"speaker\": \"Owen\", \"text\": \"Good idea. I can ___ what worked last time.\"}], \"options\": [\"take over\", \"build on\", \"turn down\"], \"answer\": \"build on\", \"explanation\": \"“build on” means develop from an existing base.\"}]\n```\n","content/anne-of-green-gables/chapter-27.md":"# Chapter 27 — Vanity and Vexation of Spirit\n\n## Story Summary — A2–B1 Level\n\nAnne still dislikes her red hair. A traveling salesman offers her a dye that he promises will turn it black. Anne secretly buys the dye and uses it. Instead of black, her hair turns a terrible green. She is horrified. Marilla eventually discovers what happened.\n\nThe color cannot easily be removed, so Anne's hair has to be cut very short. Anne admits that vanity caused the mistake. She wanted so badly to change herself that she trusted a stranger without thinking carefully.\n\nAs her hair grows back, Anne becomes less obsessed with its color. The disaster teaches her to accept herself more than before.\n\n## Conversation 1 — The Dye\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: What have you done to your hair?\nAnne: I tried to get rid of the red.\nMarilla: And it turned into green?\n\n### Phrasal Verbs\n\n- get rid of — remove something unwanted.\n- turn into — change into something different.\n\n## Conversation 2 — A Lesson\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I'll never fall for that kind of promise again.\nMarilla: Good.\nAnne: I was too caught up in wanting black hair.\nMarilla: Maybe you'll grow out of worrying about it.\n\n### Useful Expressions\n\n- fall for — believe a trick.\n- be caught up in — be deeply focused on something.\n- grow out of — stop a habit or interest as you mature.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"get rid of\", \"prompt\": \"Which expression best means “remove something unwanted”?\", \"options\": [\"take over\", \"get rid of\", \"turn down\"], \"answer\": \"get rid of\", \"explanation\": \"“get rid of” means remove something unwanted.\"}, {\"type\": \"fill\", \"target\": \"turn into\", \"prompt\": \"Complete the expression: “turn ___”\", \"answer\": \"into\", \"accepted\": [\"into\"], \"explanation\": \"The complete expression is “turn into,” meaning change into something different.\"}, {\"type\": \"dialogue\", \"target\": \"fall for\", \"prompt\": \"A fake message\", \"dialogue\": [{\"speaker\": \"Kai\", \"text\": \"Why did you click that strange link?\"}, {\"speaker\": \"Nina\", \"text\": \"The message looked like it came from my bank.\"}, {\"speaker\": \"Kai\", \"text\": \"It was a scam.\"}, {\"speaker\": \"Nina\", \"text\": \"I know. I can’t believe I ___ it.\"}], \"options\": [\"take over\", \"turn down\", \"fell for\"], \"answer\": \"fell for\", \"explanation\": \"“fall for” means believe a trick.\"}, {\"type\": \"order\", \"target\": \"be caught up in\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"caught\", \"up\", \"in\", \"work\", \"be\"], \"answer\": \"be caught up in work\", \"explanation\": \"The natural phrase is “be caught up in work.” “be caught up in” means be deeply focused on something.\"}, {\"type\": \"dialogue\", \"target\": \"grow out of\", \"prompt\": \"Old clothes\", \"dialogue\": [{\"speaker\": \"Mom\", \"text\": \"These shoes look too small.\"}, {\"speaker\": \"Teen\", \"text\": \"They were fine last month.\"}, {\"speaker\": \"Mom\", \"text\": \"Your feet are growing fast.\"}, {\"speaker\": \"Teen\", \"text\": \"I guess I’ve ___ them already.\"}], \"options\": [\"take over\", \"grown out of\", \"turn down\"], \"answer\": \"grown out of\", \"explanation\": \"“grow out of” means stop a habit or interest as you mature.\"}]\n```\n","content/anne-of-green-gables/chapter-28.md":"# Chapter 28 — An Unfortunate Lily Maid\n\n## Story Summary — A2–B1 Level\n\nAnne, Diana, Jane, and Ruby act out a romantic scene from Tennyson. Anne lies in a small boat and floats down the pond as if she were the dead heroine Elaine. At first, Anne enjoys the drama. Then she discovers that the boat is leaking.\n\nIt begins to sink. Anne manages to grab a bridge support and hangs there while the other girls run for help. Gilbert Blythe arrives in a boat and rescues her. He again apologizes for teasing her years earlier and asks if they can be friends.\n\nFor a moment, Anne considers forgiving him. But her pride returns, and she refuses. Gilbert becomes angry and leaves. Anne is safe but embarrassed by another adventure created by her love of romance.\n\nHer feelings toward Gilbert are becoming more complicated, although she still refuses to admit it.\n\n## Conversation 1 — The Boat\n\n*A modern conversation inspired by this chapter.*\n\nAnne: The boat is taking on water!\nDiana: Hold on! We'll get help!\n\n### Phrasal Verbs\n\n- take on water — begin filling with water.\n- hold on — keep holding; wait.\n- get help — find someone who can assist.\n\n## Conversation 2 — Gilbert's Offer\n\n*A modern conversation inspired by this chapter.*\n\nGilbert: Can't we put the past behind us?\nAnne: I don't know.\nGilbert: I've tried to make it up to you.\nAnne: I'm not ready to let it go.\n\n### Useful Expressions\n\n- put the past behind you — stop allowing past events to affect you.\n- make it up to someone — compensate for a wrong.\n- let it go — stop being angry about something.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"take on water\", \"prompt\": \"Which expression best means “begin filling with water”?\", \"options\": [\"take over\", \"take on water\", \"turn down\"], \"answer\": \"take on water\", \"explanation\": \"“take on water” means begin filling with water.\"}, {\"type\": \"fill\", \"target\": \"hold on\", \"prompt\": \"Complete the expression: “hold ___”\", \"answer\": \"on\", \"accepted\": [\"on\"], \"explanation\": \"The complete expression is “hold on,” meaning keep holding; wait.\"}, {\"type\": \"dialogue\", \"target\": \"get help\", \"prompt\": \"A broken sink\", \"dialogue\": [{\"speaker\": \"Tara\", \"text\": \"The kitchen sink is leaking again.\"}, {\"speaker\": \"Luis\", \"text\": \"Did tightening the pipe work?\"}, {\"speaker\": \"Tara\", \"text\": \"No, and I don’t want to make it worse.\"}, {\"speaker\": \"Luis\", \"text\": \"Then we should ___ from a plumber.\"}], \"options\": [\"turn down\", \"get help\", \"take over\"], \"answer\": \"get help\", \"explanation\": \"“get help” means find someone who can assist.\"}, {\"type\": \"order\", \"target\": \"put the past behind you\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"the\", \"past\", \"behind\", \"you\", \"put\"], \"answer\": \"put the past behind you\", \"explanation\": \"The natural phrase is “put the past behind you.” “put the past behind you” means stop allowing past events to affect you.\"}, {\"type\": \"dialogue\", \"target\": \"make it up to someone\", \"prompt\": \"Missing a birthday\", \"dialogue\": [{\"speaker\": \"Ari\", \"text\": \"I’m sorry I missed your birthday dinner.\"}, {\"speaker\": \"Maya\", \"text\": \"I know you had to work.\"}, {\"speaker\": \"Ari\", \"text\": \"Still, I feel bad.\"}, {\"speaker\": \"Maya\", \"text\": \"Then you can ___ me by buying coffee tomorrow.\"}], \"options\": [\"take over\", \"make it up to\", \"turn down\"], \"answer\": \"make it up to\", \"explanation\": \"“make it up to someone” means compensate for a wrong.\"}]\n```\n","content/anne-of-green-gables/chapter-29.md":"# Chapter 29 — An Epoch in Anne's Life\n\n## Story Summary — A2–B1 Level\n\nDiana brings exciting news: Aunt Josephine has invited both girls to Charlottetown for an exhibition. Anne is thrilled to visit the city and stay in an elegant home. At first, the expensive rooms and city life seem like things Anne has always dreamed about.\n\nBut she discovers that luxury is less magical in reality than in her imagination. The exhibition is exciting, with displays, crowds, races, and many new sights. Aunt Josephine also takes the girls out for a late treat.\n\nAnne enjoys the adventure, but she begins to miss Green Gables. Her own simple room and familiar home feel more comfortable than a grand house. When she returns, Anne tells Marilla that growing up changes the things a person wants.\n\nSome dreams are more beautiful before they become real.\n\n## Conversation 1 — The Invitation\n\n*A modern conversation inspired by this chapter.*\n\nDiana: Aunt Josephine wants us to come up to Charlottetown.\nAnne: I can hardly take it in!\nDiana: We should get ready for the trip.\n\n### Phrasal Verbs\n\n- come up to — travel to a place.\n- take in — fully understand surprising information.\n- get ready for — prepare for.\n\n## Conversation 2 — Coming Home\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: Did the city live up to your expectations?\nAnne: Not completely. I may have grown out of some dreams.\nMarilla: Green Gables has won you over.\n\n### Useful Expressions\n\n- live up to — be as good as expected.\n- grow out of — stop wanting something as you mature.\n- win someone over — cause someone to love or support something.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"come up to\", \"prompt\": \"Which expression best means “travel to a place”?\", \"options\": [\"take over\", \"come up to\", \"turn down\"], \"answer\": \"come up to\", \"explanation\": \"“come up to” means travel to a place.\"}, {\"type\": \"fill\", \"target\": \"take in\", \"prompt\": \"Complete the expression: “take ___”\", \"answer\": \"in\", \"accepted\": [\"in\"], \"explanation\": \"The complete expression is “take in,” meaning fully understand surprising information.\"}, {\"type\": \"dialogue\", \"target\": \"get ready for\", \"prompt\": \"A morning flight\", \"dialogue\": [{\"speaker\": \"Nia\", \"text\": \"Your flight leaves at seven tomorrow, right?\"}, {\"speaker\": \"Eli\", \"text\": \"Yes, so I need to leave home at five.\"}, {\"speaker\": \"Nia\", \"text\": \"Have you packed yet?\"}, {\"speaker\": \"Eli\", \"text\": \"Not completely. I’m still ___ the trip.\"}], \"options\": [\"getting ready for\", \"take over\", \"turn down\"], \"answer\": \"getting ready for\", \"explanation\": \"“get ready for” means prepare for.\"}, {\"type\": \"order\", \"target\": \"live up to\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"up\", \"to\", \"expectations\", \"live\"], \"answer\": \"live up to expectations\", \"explanation\": \"The natural phrase is “live up to expectations.” “live up to” means be as good as expected.\"}, {\"type\": \"dialogue\", \"target\": \"win someone over\", \"prompt\": \"A skeptical client\", \"dialogue\": [{\"speaker\": \"Leo\", \"text\": \"The client didn’t like our idea at first.\"}, {\"speaker\": \"Mina\", \"text\": \"What changed?\"}, {\"speaker\": \"Leo\", \"text\": \"We showed them a simple prototype.\"}, {\"speaker\": \"Mina\", \"text\": \"So that helped ___ them?\"}], \"options\": [\"take over\", \"win over\", \"turn down\"], \"answer\": \"win over\", \"explanation\": \"“win someone over” means cause someone to love or support something.\"}]\n```\n","content/anne-of-green-gables/chapter-30.md":"# Chapter 30 — The Queen's Class Is Organized\n\n## Story Summary — A2–B1 Level\n\nMiss Stacy organizes a special class for students who want to take the entrance examination for Queen's Academy. Anne joins along with Gilbert and several other Avonlea students. The work is demanding. Anne studies seriously because success at Queen's can lead to a teaching license and further education.\n\nHer rivalry with Gilbert continues, but it has changed. They still compete for the highest marks, yet Anne increasingly respects his intelligence. Diana does not plan to attend Queen's. Anne is sad because she realizes their lives may soon move in different directions.\n\nAnne is also changing. She is taller, quieter, and less likely to speak every thought aloud. Studying for Queen's gives her a new kind of dream: a goal that requires discipline and hard work.\n\n## Conversation 1 — The New Class\n\n*A modern conversation inspired by this chapter.*\n\nMiss Stacy: I'm putting together a Queen's class.\nAnne: I'd like to sign up.\nMiss Stacy: You'll have to keep up with extra work.\n\n### Phrasal Verbs\n\n- put together — organize or create.\n- sign up — register.\n- keep up with — stay at the required pace.\n\n## Conversation 2 — Different Paths\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I wish you were going on to Queen's.\nDiana: It isn't my path.\nAnne: I hope we don't drift apart.\n\n### Useful Expressions\n\n- go on to — continue to a next stage.\n- drift apart — gradually become less close.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"put together\", \"prompt\": \"Which expression best means “organize or create”?\", \"options\": [\"take over\", \"put together\", \"turn down\"], \"answer\": \"put together\", \"explanation\": \"“put together” means organize or create.\"}, {\"type\": \"fill\", \"target\": \"sign up\", \"prompt\": \"Complete the expression: “sign ___”\", \"answer\": \"up\", \"accepted\": [\"up\"], \"explanation\": \"The complete expression is “sign up,” meaning register.\"}, {\"type\": \"dialogue\", \"target\": \"keep up with\", \"prompt\": \"A busy week at work\", \"dialogue\": [{\"speaker\": \"Nina\", \"text\": \"You look exhausted. Is everything okay?\"}, {\"speaker\": \"Sam\", \"text\": \"We have three deadlines this week.\"}, {\"speaker\": \"Nina\", \"text\": \"Are you managing all the new tasks?\"}, {\"speaker\": \"Sam\", \"text\": \"Barely. I’m having trouble ___ all the emails and meetings.\"}], \"options\": [\"take over\", \"turn down\", \"keeping up with\"], \"answer\": \"keeping up with\", \"explanation\": \"“keep up with” means stay at the required pace.\"}, {\"type\": \"order\", \"target\": \"go on to\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"on\", \"to\", \"college\", \"go\"], \"answer\": \"go on to college\", \"explanation\": \"The natural phrase is “go on to college.” “go on to” means continue to a next stage.\"}, {\"type\": \"dialogue\", \"target\": \"drift apart\", \"prompt\": \"Old friends\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"Do you still talk to your college roommate?\"}, {\"speaker\": \"Leo\", \"text\": \"Not very often anymore.\"}, {\"speaker\": \"Mia\", \"text\": \"Did something happen?\"}, {\"speaker\": \"Leo\", \"text\": \"No, we just slowly ___ after moving to different cities.\"}], \"options\": [\"take over\", \"drifted apart\", \"turn down\"], \"answer\": \"drifted apart\", \"explanation\": \"“drift apart” means gradually become less close.\"}]\n```\n","content/anne-of-green-gables/chapter-31.md":"# Chapter 31 — Where the Brook and River Meet\n\n## Story Summary — A2–B1 Level\n\nAnne is about fifteen and clearly moving from childhood into young adulthood. Even Mrs. Rachel admits that she has become attractive. Marilla feels proud but also a little sad.\n\nShe misses the endlessly talkative child who first came to Green Gables. Anne still has imagination, but she keeps more thoughts inside. Anne continues preparing for the Queen's examination.\n\nShe works hard but sometimes becomes anxious about whether she will succeed. Her writing is changing too. Under Miss Stacy's guidance, she becomes less interested in exaggerated romance and more interested in honest, clear writing. Anne and Diana know that Anne may soon leave Avonlea for school.\n\nTheir friendship remains strong, but childhood is ending.\n\n## Conversation 1 — Growing Up\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: You've certainly grown up.\nAnne: I still think just as much.\nMarilla: You don't chatter away like before.\nAnne: I keep more to myself now.\n\n### Phrasal Verbs\n\n- grow up — develop into an adult.\n- chatter away — talk continuously.\n- keep to yourself — not share everything with others.\n\n## Conversation 2 — Exam Worries\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I don't want to fall short.\nDiana: You need to settle down and trust yourself.\nAnne: You're right. I shouldn't wear myself out.\n\n### Useful Expressions\n\n- fall short — fail to reach a desired level.\n- settle down — become calm and focused.\n- wear yourself out — make yourself extremely tired.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"grow up\", \"prompt\": \"Which expression best means “develop into an adult”?\", \"options\": [\"take over\", \"grow up\", \"turn down\"], \"answer\": \"grow up\", \"explanation\": \"“grow up” means develop into an adult.\"}, {\"type\": \"fill\", \"target\": \"chatter away\", \"prompt\": \"Complete the expression: “chatter ___”\", \"answer\": \"away\", \"accepted\": [\"away\"], \"explanation\": \"The complete expression is “chatter away,” meaning talk continuously.\"}, {\"type\": \"dialogue\", \"target\": \"keep to yourself\", \"prompt\": \"A quiet coworker\", \"dialogue\": [{\"speaker\": \"Sam\", \"text\": \"Does Priya join the team for lunch?\"}, {\"speaker\": \"Lena\", \"text\": \"Not very often.\"}, {\"speaker\": \"Sam\", \"text\": \"Is she unfriendly?\"}, {\"speaker\": \"Lena\", \"text\": \"No, she just tends to ___ at work.\"}], \"options\": [\"turn down\", \"keep to herself\", \"take over\"], \"answer\": \"keep to herself\", \"explanation\": \"“keep to yourself” means not share everything with others.\"}, {\"type\": \"order\", \"target\": \"fall short\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"short\", \"of\", \"the\", \"goal\", \"fall\"], \"answer\": \"fall short of the goal\", \"explanation\": \"The natural phrase is “fall short of the goal.” “fall short” means fail to reach a desired level.\"}, {\"type\": \"dialogue\", \"target\": \"wear yourself out\", \"prompt\": \"Too many errands\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"You’ve been running around all day.\"}, {\"speaker\": \"Ben\", \"text\": \"I still have three errands left.\"}, {\"speaker\": \"Mia\", \"text\": \"They can wait until tomorrow.\"}, {\"speaker\": \"Ben\", \"text\": \"You’re right. I don’t want to ___.\"}], \"options\": [\"take over\", \"wear myself out\", \"turn down\"], \"answer\": \"wear myself out\", \"explanation\": \"“wear yourself out” means make yourself extremely tired.\"}]\n```\n","content/anne-of-green-gables/chapter-32.md":"# Chapter 32 — The Pass List Is Out\n\n## Story Summary — A2–B1 Level\n\nAnne and the other Queen's candidates finish their time at Avonlea school. Saying goodbye to Miss Stacy and their old school life is emotional. Anne goes to Charlottetown to take the entrance examinations.\n\nShe is nervous but follows Miss Stacy's advice not to study desperately at the last minute. Afterward, Anne returns to Green Gables and waits for the results. The waiting feels almost worse than the exams.\n\nFinally, the newspaper publishes the pass list. All the Avonlea students have passed. Even more exciting, Anne and Gilbert have tied for first place on Prince Edward Island. Matthew, Marilla, Diana, and Mrs. Rachel are extremely proud.\n\nAnne has earned a place at Queen's Academy and proved what talent and hard work can accomplish.\n\n## Conversation 1 — Waiting\n\n*A modern conversation inspired by this chapter.*\n\nDiana: Have the results come out?\nAnne: Not yet. The waiting is wearing me down.\nDiana: I'm sure you got through.\n\n### Phrasal Verbs\n\n- come out — be published or become available.\n- wear someone down — gradually make someone tired or worried.\n- get through — successfully pass or complete something.\n\n## Conversation 2 — Good News\n\n*A modern conversation inspired by this chapter.*\n\nDiana: You and Gilbert came out on top!\nAnne: We tied for first?\nDiana: All that work paid off.\n\n### Useful Expressions\n\n- come out on top — finish in the best position.\n- pay off — produce a good result after effort.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"come out\", \"prompt\": \"Which expression best means “be published or become available”?\", \"options\": [\"take over\", \"come out\", \"turn down\"], \"answer\": \"come out\", \"explanation\": \"“come out” means be published or become available.\"}, {\"type\": \"fill\", \"target\": \"wear someone down\", \"prompt\": \"Complete the expression: “wear someone ___”\", \"answer\": \"down\", \"accepted\": [\"down\"], \"explanation\": \"The complete expression is “wear someone down,” meaning gradually make someone tired or worried.\"}, {\"type\": \"dialogue\", \"target\": \"get through\", \"prompt\": \"A long phone queue\", \"dialogue\": [{\"speaker\": \"Jin\", \"text\": \"Were you able to reach the airline?\"}, {\"speaker\": \"Nora\", \"text\": \"Eventually.\"}, {\"speaker\": \"Jin\", \"text\": \"You were on hold forever.\"}, {\"speaker\": \"Nora\", \"text\": \"Yes, but I finally ___ to an agent.\"}], \"options\": [\"got through\", \"take over\", \"turn down\"], \"answer\": \"got through\", \"explanation\": \"“get through” means successfully pass or complete something.\"}, {\"type\": \"order\", \"target\": \"come out on top\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"out\", \"on\", \"top\", \"come\"], \"answer\": \"come out on top\", \"explanation\": \"The natural phrase is “come out on top.” “come out on top” means finish in the best position.\"}, {\"type\": \"dialogue\", \"target\": \"pay off\", \"prompt\": \"Studying regularly\", \"dialogue\": [{\"speaker\": \"Ava\", \"text\": \"You got the highest score in the class.\"}, {\"speaker\": \"Max\", \"text\": \"I studied a little every day for a month.\"}, {\"speaker\": \"Ava\", \"text\": \"That was a lot of work.\"}, {\"speaker\": \"Max\", \"text\": \"Yes, but it really ___.\"}], \"options\": [\"take over\", \"paid off\", \"turn down\"], \"answer\": \"paid off\", \"explanation\": \"“pay off” means produce a good result after effort.\"}]\n```\n","content/anne-of-green-gables/chapter-33.md":"# Chapter 33 — The Hotel Concert\n\n## Story Summary — A2–B1 Level\n\nAnne is invited to perform a recitation at a fashionable hotel at White Sands. Diana helps her choose what to wear, and Anne wears the pearl necklace Matthew gave her. When Anne sees elegant women in expensive clothes and jewelry, she suddenly feels plain and out of place.\n\nOn stage, her nervousness becomes worse. She is tempted to give up. Then she sees Gilbert in the audience, and her pride gives her courage. Anne performs beautifully and receives strong applause.\n\nAfterward, she realizes that wealthy, elegant people are simply human beings. Their clothes do not make them more important. The experience strengthens Anne's confidence.\n\nShe learns to focus on what she can do instead of comparing herself with others.\n\n## Conversation 1 — Before the Performance\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I don't fit in here.\nDiana: Don't compare yourself to them.\nAnne: I need to pull myself together.\n\n### Phrasal Verbs\n\n- fit in — feel accepted in a group.\n- compare yourself to — judge yourself against someone else.\n- pull yourself together — calm yourself and regain control.\n\n## Conversation 2 — Afterward\n\n*A modern conversation inspired by this chapter.*\n\nDiana: You pulled it off!\nAnne: I almost ran away.\nDiana: But you went through with it.\nAnne: The fear wore off once I started.\n\n### Useful Expressions\n\n- pull it off — succeed at something difficult.\n- go through with — complete something despite difficulty.\n- wear off — gradually disappear.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"fit in\", \"prompt\": \"Which expression best means “feel accepted in a group”?\", \"options\": [\"take over\", \"fit in\", \"turn down\"], \"answer\": \"fit in\", \"explanation\": \"“fit in” means feel accepted in a group.\"}, {\"type\": \"fill\", \"target\": \"compare yourself to\", \"prompt\": \"Complete the expression: “compare yourself ___”\", \"answer\": \"to\", \"accepted\": [\"to\"], \"explanation\": \"The complete expression is “compare yourself to,” meaning judge yourself against someone else.\"}, {\"type\": \"dialogue\", \"target\": \"pull yourself together\", \"prompt\": \"Before a presentation\", \"dialogue\": [{\"speaker\": \"Lia\", \"text\": \"I’m so nervous I can barely think.\"}, {\"speaker\": \"Dan\", \"text\": \"Take two slow breaths.\"}, {\"speaker\": \"Lia\", \"text\": \"The presentation starts in five minutes.\"}, {\"speaker\": \"Dan\", \"text\": \"You can do this. Just ___ and focus on the first slide.\"}], \"options\": [\"take over\", \"turn down\", \"pull yourself together\"], \"answer\": \"pull yourself together\", \"explanation\": \"“pull yourself together” means calm yourself and regain control.\"}, {\"type\": \"order\", \"target\": \"pull it off\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"it\", \"off\", \"pull\"], \"answer\": \"pull it off\", \"explanation\": \"The natural phrase is “pull it off.” “pull it off” means succeed at something difficult.\"}, {\"type\": \"dialogue\", \"target\": \"wear off\", \"prompt\": \"Pain medicine\", \"dialogue\": [{\"speaker\": \"Maya\", \"text\": \"Is your headache better?\"}, {\"speaker\": \"Leo\", \"text\": \"It was, but it’s starting to hurt again.\"}, {\"speaker\": \"Maya\", \"text\": \"Did the medicine stop working?\"}, {\"speaker\": \"Leo\", \"text\": \"I think the effect is beginning to ___.\"}], \"options\": [\"take over\", \"wear off\", \"turn down\"], \"answer\": \"wear off\", \"explanation\": \"“wear off” means gradually disappear.\"}]\n```\n","content/anne-of-green-gables/chapter-34.md":"# Chapter 34 — A Queen's Girl\n\n## Story Summary — A2–B1 Level\n\nAnne leaves Green Gables to attend Queen's Academy in Charlottetown. The move is exciting but difficult because she has never lived away from the home she loves. At Queen's, Anne meets talented students and begins an intense academic year.\n\nShe works hard toward a teaching license. Gilbert is also there. Their rivalry continues, but Anne no longer feels the same anger. She respects him and sometimes wishes they could be friends.\n\nAnne makes new friends while staying close to Avonlea through letters and visits. She especially misses Marilla, Matthew, Diana, and Green Gables. Her ambitions grow. Anne decides to compete for the Avery Scholarship, which could allow her to continue at Redmond College.\n\n## Conversation 1 — Leaving Home\n\n*A modern conversation inspired by this chapter.*\n\nDiana: Are you ready to move away?\nAnne: It's hard to leave Green Gables behind.\nDiana: You'll settle in once classes begin.\n\n### Phrasal Verbs\n\n- move away — leave your home area to live elsewhere.\n- leave behind — go away from people or places.\n- settle in — become comfortable in a new place.\n\n## Conversation 2 — New Goals\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I'm going for the Avery Scholarship.\nFriend: If you keep up your grades, you have a chance.\nAnne: Then I'm going to go for it.\n\n### Useful Expressions\n\n- go for — try to achieve something.\n- keep up — maintain a standard.\n- go for it — try enthusiastically.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"move away\", \"prompt\": \"Which expression best means “leave your home area to live elsewhere”?\", \"options\": [\"take over\", \"move away\", \"turn down\"], \"answer\": \"move away\", \"explanation\": \"“move away” means leave your home area to live elsewhere.\"}, {\"type\": \"fill\", \"target\": \"leave behind\", \"prompt\": \"Complete the expression: “leave ___”\", \"answer\": \"behind\", \"accepted\": [\"behind\"], \"explanation\": \"The complete expression is “leave behind,” meaning go away from people or places.\"}, {\"type\": \"dialogue\", \"target\": \"settle in\", \"prompt\": \"A new apartment\", \"dialogue\": [{\"speaker\": \"Owen\", \"text\": \"How’s the new apartment?\"}, {\"speaker\": \"Nina\", \"text\": \"Still full of boxes.\"}, {\"speaker\": \"Owen\", \"text\": \"Do you feel at home yet?\"}, {\"speaker\": \"Nina\", \"text\": \"Not quite, but I’m starting to ___.\"}], \"options\": [\"turn down\", \"settle in\", \"take over\"], \"answer\": \"settle in\", \"explanation\": \"“settle in” means become comfortable in a new place.\"}, {\"type\": \"order\", \"target\": \"go for\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"for\", \"the\", \"job\", \"go\"], \"answer\": \"go for the job\", \"explanation\": \"The natural phrase is “go for the job.” “go for” means try to achieve something.\"}, {\"type\": \"dialogue\", \"target\": \"keep up\", \"prompt\": \"A fast walking group\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"Why are you breathing so hard?\"}, {\"speaker\": \"Tom\", \"text\": \"Everyone is walking really fast.\"}, {\"speaker\": \"Mia\", \"text\": \"Do you want them to slow down?\"}, {\"speaker\": \"Tom\", \"text\": \"Maybe. I’m struggling to ___.\"}], \"options\": [\"take over\", \"keep up\", \"turn down\"], \"answer\": \"keep up\", \"explanation\": \"“keep up” means maintain a standard.\"}]\n```\n","content/anne-of-green-gables/chapter-35.md":"# Chapter 35 — The Winter at Queen's\n\n## Story Summary — A2–B1 Level\n\nWinter at Queen's passes quickly because Anne is busy with classes and studying. She becomes more comfortable in Charlottetown and makes new friends. Her competition with Gilbert remains strong but is now respectful rather than hostile.\n\nAnne recognizes that Gilbert is a worthy opponent and that competing with him has helped her improve. Anne sometimes wishes they were friends, but her old pride still stops her from making the first move. She continues preparing for the final examinations and the Avery Scholarship.\n\nHer goals are demanding, but she has learned to work steadily. Anne still values imagination, beauty, and friendship, but ambition has become another important part of her personality. She also understands more clearly that doing her best matters even if she does not always win.\n\n## Conversation 1 — Keeping Up\n\n*A modern conversation inspired by this chapter.*\n\nFriend: How are you keeping up with the work?\nAnne: I've got into a good routine.\nFriend: Still trying to beat out Gilbert?\nAnne: I want to do well, but winning isn't everything.\n\n### Phrasal Verbs\n\n- keep up with — stay at the same pace.\n- get into — develop a habit or routine.\n- beat out — defeat someone in a competition.\n\n## Conversation 2 — A Changing Rivalry\n\n*A modern conversation inspired by this chapter.*\n\nFriend: Why don't you two make peace?\nAnne: Sometimes I want to.\nFriend: What holds you back?\nAnne: Pride. I should probably let go of it.\n\n### Useful Expressions\n\n- make peace — end a conflict.\n- hold back — prevent someone from acting.\n- let go of — stop holding onto an emotion.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"keep up with\", \"prompt\": \"Which expression best means “stay at the same pace”?\", \"options\": [\"take over\", \"keep up with\", \"turn down\"], \"answer\": \"keep up with\", \"explanation\": \"“keep up with” means stay at the same pace.\"}, {\"type\": \"fill\", \"target\": \"get into\", \"prompt\": \"Complete the expression: “get ___”\", \"answer\": \"into\", \"accepted\": [\"into\"], \"explanation\": \"The complete expression is “get into,” meaning develop a habit or routine.\"}, {\"type\": \"dialogue\", \"target\": \"beat out\", \"prompt\": \"A job competition\", \"dialogue\": [{\"speaker\": \"Nora\", \"text\": \"Did Maya get the internship?\"}, {\"speaker\": \"Evan\", \"text\": \"Yes. More than fifty people applied.\"}, {\"speaker\": \"Nora\", \"text\": \"Wow, that was competitive.\"}, {\"speaker\": \"Evan\", \"text\": \"She managed to ___ all the other candidates.\"}], \"options\": [\"beat out\", \"take over\", \"turn down\"], \"answer\": \"beat out\", \"explanation\": \"“beat out” means defeat someone in a competition.\"}, {\"type\": \"order\", \"target\": \"make peace\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"peace\", \"with\", \"him\", \"make\"], \"answer\": \"make peace with him\", \"explanation\": \"The natural phrase is “make peace with him.” “make peace” means end a conflict.\"}, {\"type\": \"dialogue\", \"target\": \"let go of\", \"prompt\": \"An old argument\", \"dialogue\": [{\"speaker\": \"Kim\", \"text\": \"Are you still thinking about what he said last month?\"}, {\"speaker\": \"Leo\", \"text\": \"A little.\"}, {\"speaker\": \"Kim\", \"text\": \"You already talked it through.\"}, {\"speaker\": \"Leo\", \"text\": \"I know. I need to ___ the resentment.\"}], \"options\": [\"take over\", \"let go of\", \"turn down\"], \"answer\": \"let go of\", \"explanation\": \"“let go of” means stop holding onto an emotion.\"}]\n```\n","content/anne-of-green-gables/chapter-36.md":"# Chapter 36 — The Glory and the Dream\n\n## Story Summary — A2–B1 Level\n\nThe final examination results are announced. Gilbert wins the Gold Medal, while Anne wins the Avery Scholarship. The scholarship means Anne can attend Redmond College.\n\nShe is thrilled. Years of study have opened a future she once could hardly imagine. Anne returns to Green Gables. Matthew tells her how proud he is and reminds her that he always preferred having her, even though he and Marilla originally asked for a boy. Anne is deeply happy: she has a loving home, academic success, and a promising future.\n\nAt the same time, there are signs of trouble. Matthew has heart problems, and Marilla's eyesight is becoming worse. Anne does not yet understand how quickly her plans may change.\n\n## Conversation 1 — The Scholarship\n\n*A modern conversation inspired by this chapter.*\n\nDiana: You won!\nAnne: I can't take it in.\nDiana: All that work paid off.\nAnne: Redmond suddenly feels possible.\n\n### Phrasal Verbs\n\n- take in — fully understand surprising news.\n- pay off — produce a successful result.\n\n## Conversation 2 — Matthew's Pride\n\n*A modern conversation inspired by this chapter.*\n\nMatthew: You've turned out just fine.\nAnne: You and Marilla took me in and gave me a home.\nMatthew: And we're proud of you.\n\n### Useful Expressions\n\n- turn out — develop in a particular way.\n- take someone in — give someone a home.\n\n- look ahead to — think about or plan for something in the future. She was already looking ahead to the next stage of her life.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"take in\", \"prompt\": \"Which expression best means “fully understand surprising news”?\", \"options\": [\"take over\", \"take in\", \"turn down\"], \"answer\": \"take in\", \"explanation\": \"“take in” means fully understand surprising news.\"}, {\"type\": \"fill\", \"target\": \"pay off\", \"prompt\": \"Complete the expression: “pay ___”\", \"answer\": \"off\", \"accepted\": [\"off\"], \"explanation\": \"The complete expression is “pay off,” meaning produce a successful result.\"}, {\"type\": \"dialogue\", \"target\": \"turn out\", \"prompt\": \"A new restaurant\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"Was the new restaurant good?\"}, {\"speaker\": \"Sam\", \"text\": \"I was unsure because the reviews were mixed.\"}, {\"speaker\": \"Mia\", \"text\": \"So how was it?\"}, {\"speaker\": \"Sam\", \"text\": \"It ___ to be excellent.\"}], \"options\": [\"take over\", \"turn down\", \"turned out\"], \"answer\": \"turned out\", \"explanation\": \"“turn out” means develop in a particular way.\"}, {\"type\": \"order\", \"target\": \"take someone in\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"her\", \"in\", \"take\"], \"answer\": \"take her in\", \"explanation\": \"The natural phrase is “take her in.” “take someone in” means give someone a home.\"}, {\"type\": \"dialogue\", \"target\": \"look ahead to\", \"prompt\": \"Planning next year\", \"dialogue\": [{\"speaker\": \"Nina\", \"text\": \"You finish this course next month.\"}, {\"speaker\": \"Ari\", \"text\": \"I know. It went by quickly.\"}, {\"speaker\": \"Nina\", \"text\": \"What comes next?\"}, {\"speaker\": \"Ari\", \"text\": \"I’m already ___ a new job and a move.\"}], \"options\": [\"take over\", \"looking ahead to\", \"turn down\"], \"answer\": \"looking ahead to\", \"explanation\": \"“look ahead to” means think about or plan for something in the future.\"}]\n```\n","content/anne-of-green-gables/chapter-37.md":"# Chapter 37 — The Reaper Whose Name Is Death\n\n## Story Summary — A2–B1 Level\n\nSoon after Anne returns, tragedy strikes. Matthew learns that the bank where he and Marilla kept their savings has failed. The shock is too much for his weak heart.\n\nHe collapses at the doorway of Green Gables and dies. Anne is stunned. At first, her grief is so deep that she cannot cry. Matthew was the first person at Green Gables to accept her completely, and his quiet love always made her feel safe.\n\nLater, Anne remembers his loving words and finally cries. After the funeral, life slowly begins moving again. Anne feels guilty when she notices beauty or experiences happiness, but Mrs. Allan helps her understand that continuing to live does not mean she loved Matthew less.\n\nAnne and Marilla become closer in their shared grief. Matthew's death marks the end of Anne's childhood in a powerful way, and the future she imagined can no longer continue unchanged.\n\n## Conversation 1 — The Loss\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I don't know how we'll get through this.\nMarilla: We'll have to lean on each other.\nAnne: I keep expecting Matthew to walk through the door.\n\n### Phrasal Verbs\n\n- get through — survive a difficult period.\n- lean on — depend on someone for emotional support.\n\n## Conversation 2 — Moving Forward\n\n*A modern conversation inspired by this chapter.*\n\nAnne: It feels strange to carry on.\nMrs. Allan: You don't have to shut out every happy moment.\nAnne: I'll always hold on to Matthew's memory.\n\n### Useful Expressions\n\n- carry on — continue despite difficulty.\n- shut out — prevent something or someone from entering your life or thoughts.\n- hold on to — keep something emotionally or physically.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"get through\", \"prompt\": \"Which expression best means “survive a difficult period”?\", \"options\": [\"take over\", \"get through\", \"turn down\"], \"answer\": \"get through\", \"explanation\": \"“get through” means survive a difficult period.\"}, {\"type\": \"fill\", \"target\": \"lean on\", \"prompt\": \"Complete the expression: “lean ___”\", \"answer\": \"on\", \"accepted\": [\"on\"], \"explanation\": \"The complete expression is “lean on,” meaning depend on someone for emotional support.\"}, {\"type\": \"dialogue\", \"target\": \"carry on\", \"prompt\": \"After an interruption\", \"dialogue\": [{\"speaker\": \"Teacher\", \"text\": \"Sorry about the fire alarm.\"}, {\"speaker\": \"Student\", \"text\": \"Are we still finishing the lesson?\"}, {\"speaker\": \"Teacher\", \"text\": \"Yes, everyone is back now.\"}, {\"speaker\": \"Student\", \"text\": \"Great. We can ___ where we left off.\"}], \"options\": [\"turn down\", \"carry on\", \"take over\"], \"answer\": \"carry on\", \"explanation\": \"“carry on” means continue despite difficulty.\"}, {\"type\": \"order\", \"target\": \"shut out\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"everyone\", \"out\", \"shut\"], \"answer\": \"shut everyone out\", \"explanation\": \"The natural phrase is “shut everyone out.” “shut out” means prevent something or someone from entering your life or thoughts.\"}, {\"type\": \"dialogue\", \"target\": \"hold on to\", \"prompt\": \"A meaningful letter\", \"dialogue\": [{\"speaker\": \"Mia\", \"text\": \"You still have that old letter?\"}, {\"speaker\": \"Ben\", \"text\": \"Yes. My grandfather wrote it to me years ago.\"}, {\"speaker\": \"Mia\", \"text\": \"It must mean a lot to you.\"}, {\"speaker\": \"Ben\", \"text\": \"It does. I want to ___ it forever.\"}], \"options\": [\"take over\", \"hold on to\", \"turn down\"], \"answer\": \"hold on to\", \"explanation\": \"“hold on to” means keep something emotionally or physically.\"}]\n```\n","content/anne-of-green-gables/chapter-38.md":"# Chapter 38 — The Bend in the Road\n\n## Story Summary — A2–B1 Level\n\nAfter Matthew's death, Marilla visits an eye specialist and receives frightening news. Her eyesight is failing, and she must avoid strain or she may become blind. Anne realizes that Marilla cannot manage Green Gables alone.\n\nMarilla even considers selling the farm. Anne makes a major decision. She gives up the Avery Scholarship and her plan to attend Redmond College. Instead, she will stay near Green Gables, become a teacher, and take care of Marilla.\n\nAt first, Anne plans to teach at Carmody because Gilbert has been offered the Avonlea school. Then Mrs. Rachel brings surprising news: Gilbert has given up the Avonlea position so Anne can have it and stay close to Marilla. He will teach farther away. Anne is deeply touched.\n\nWhen she meets Gilbert, she thanks him and finally ends their long silence. They agree to become friends. Anne's future is very different from the one she imagined. Yet she does not see her new path as the end of her dreams.\n\nShe thinks of life as a road with a bend in it: she cannot see everything ahead, but the unknown future can still be meaningful and beautiful. The novel ends with Anne at Green Gables, surrounded by love, responsibility, friendship, and hope.\n\n## Conversation 1 — A New Decision\n\n*A modern conversation inspired by this chapter.*\n\nMarilla: You shouldn't give up Redmond because of me.\nAnne: I'm not giving up my future. I'm changing course.\nMarilla: What will you do?\nAnne: Teach nearby and look after you.\n\n### Phrasal Verbs\n\n- give up — stop pursuing something.\n- change course — choose a different direction or plan.\n- look after — take care of.\n\n## Conversation 2 — Anne and Gilbert\n\n*A modern conversation inspired by this chapter.*\n\nAnne: I heard you gave up the Avonlea school for me.\nGilbert: I knew you needed to stay near home.\nAnne: I'd like to start over.\nGilbert: So would I.\nAnne: Then let's put the past behind us.\nGilbert: Friends?\nAnne: Friends.\n\n### Useful Expressions\n\n- give up — let someone else have something or stop having it.\n- start over — begin again in a new way.\n- put the past behind you — stop allowing an old conflict to control the present.\n\n## Practice\n\n```exercise\n[{\"type\": \"choice\", \"target\": \"give up\", \"prompt\": \"Which expression best means “let someone else have something or stop having it”?\", \"options\": [\"take over\", \"give up\", \"turn down\"], \"answer\": \"give up\", \"explanation\": \"“give up” means let someone else have something or stop having it.\"}, {\"type\": \"fill\", \"target\": \"change course\", \"prompt\": \"Complete the expression: “change ___”\", \"answer\": \"course\", \"accepted\": [\"course\"], \"explanation\": \"The complete expression is “change course,” meaning choose a different direction or plan.\"}, {\"type\": \"dialogue\", \"target\": \"look after\", \"prompt\": \"A friend’s plants\", \"dialogue\": [{\"speaker\": \"Eva\", \"text\": \"I’m away for ten days next month.\"}, {\"speaker\": \"Jon\", \"text\": \"Sounds nice.\"}, {\"speaker\": \"Eva\", \"text\": \"I’m worried my plants will dry out.\"}, {\"speaker\": \"Jon\", \"text\": \"I can ___ them while you’re gone.\"}], \"options\": [\"look after\", \"take over\", \"turn down\"], \"answer\": \"look after\", \"explanation\": \"“look after” means take care of.\"}, {\"type\": \"order\", \"target\": \"start over\", \"prompt\": \"Tap the words in the natural order.\", \"tokens\": [\"over\", \"start\"], \"answer\": \"start over\", \"explanation\": \"The natural phrase is “start over.” “start over” means begin again in a new way.\"}, {\"type\": \"dialogue\", \"target\": \"put the past behind you\", \"prompt\": \"Moving on after conflict\", \"dialogue\": [{\"speaker\": \"Maya\", \"text\": \"Are things better between you and Chris?\"}, {\"speaker\": \"Leo\", \"text\": \"Yes. We finally talked honestly.\"}, {\"speaker\": \"Maya\", \"text\": \"That must feel good.\"}, {\"speaker\": \"Leo\", \"text\": \"It does. We’re ready to ___ now.\"}], \"options\": [\"take over\", \"put the past behind us\", \"turn down\"], \"answer\": \"put the past behind us\", \"explanation\": \"“put the past behind you” means stop allowing an old conflict to control the present.\"}]\n```\n"}};
